Да, можно. Ниже — готовая **одностраничная HTML-страница**, которая:

- загружает бинарный `.PR1`;
- разбирает его как записи `[id:uint16][len:uint16][value:len bytes]`;
- показывает:
  - `ID`
  - длину
  - тип (`double` / `string` / `bytes`)
  - значение
- позволяет **редактировать строки и double-поля**;
- сохраняет изменённый файл обратно.

Сразу оговорюсь: это рабочая основа для вашего формата, который по дампу выглядит именно так. Если позже окажется, что часть записей имеет более сложную вложенную структуру — страницу можно расширить.

Сохраните как `pr1_editor.html` и откройте в браузере.

```html name=pr1_editor.html
<!doctype html>
<html lang="ru">
<head>
  <meta charset="UTF-8" />
  <title>PR1 Editor</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      margin: 20px;
      background: #f5f5f5;
      color: #222;
    }
    h1 {
      margin-top: 0;
    }
    .toolbar {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
      margin-bottom: 16px;
    }
    .toolbar input[type="file"] {
      padding: 6px;
      background: white;
      border: 1px solid #ccc;
    }
    .toolbar input[type="text"] {
      padding: 8px;
      min-width: 260px;
      border: 1px solid #ccc;
      border-radius: 4px;
    }
    .toolbar button {
      padding: 8px 12px;
      border: 1px solid #888;
      background: white;
      cursor: pointer;
      border-radius: 4px;
    }
    .toolbar button:hover {
      background: #eee;
    }
    .info {
      margin-bottom: 10px;
      font-size: 14px;
      color: #444;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      background: white;
    }
    th, td {
      border: 1px solid #ddd;
      padding: 6px 8px;
      vertical-align: top;
      font-size: 13px;
    }
    th {
      background: #fafafa;
      position: sticky;
      top: 0;
      z-index: 2;
    }
    tr:nth-child(even) {
      background: #fcfcfc;
    }
    .cell-mono {
      font-family: Consolas, monospace;
      white-space: nowrap;
    }
    .editable {
      width: 100%;
      box-sizing: border-box;
      padding: 4px 6px;
      font-size: 13px;
    }
    .readonly-bytes {
      font-family: Consolas, monospace;
      font-size: 12px;
      color: #555;
      max-width: 500px;
      word-break: break-all;
    }
    .row-changed {
      background: #fff8d6 !important;
    }
    .small {
      font-size: 12px;
      color: #666;
    }
    .warn {
      color: #a94442;
      font-weight: bold;
    }
    .ok {
      color: #2e7d32;
      font-weight: bold;
    }
  </style>
</head>
<body>
  <h1>Редактор PR1</h1>

  <div class="toolbar">
    <input type="file" id="fileInput" />
    <input type="text" id="searchInput" placeholder="Поиск по ID, значению, строке..." />
    <button id="saveBtn" disabled>Скачать изменённый файл</button>
    <button id="resetBtn" disabled>Сбросить изменения</button>
  </div>

  <div class="info" id="status">Загрузите файл .PR1</div>
  <div class="info small">
    Формат разбора: <span class="cell-mono">[id:uint16][len:uint16][value:len bytes]</span>, little-endian.
    Редактирование включено для строк и чисел double (8 байт).
  </div>

  <table id="recordsTable">
    <thead>
      <tr>
        <th>#</th>
        <th>Offset</th>
        <th>ID (hex)</th>
        <th>ID (dec)</th>
        <th>Len</th>
        <th>Тип</th>
        <th>Значение</th>
        <th>Raw bytes</th>
      </tr>
    </thead>
    <tbody></tbody>
  </table>

  <script>
    let originalBuffer = null;
    let workingBuffer = null;
    let records = [];
    let originalFileName = "edited.PR1";

    const fileInput = document.getElementById("fileInput");
    const searchInput = document.getElementById("searchInput");
    const saveBtn = document.getElementById("saveBtn");
    const resetBtn = document.getElementById("resetBtn");
    const statusEl = document.getElementById("status");
    const tbody = document.querySelector("#recordsTable tbody");

    function bytesToHex(bytes, maxLen = 64) {
      const arr = Array.from(bytes).map(b => b.toString(16).padStart(2, "0").toUpperCase());
      if (arr.length > maxLen) {
        return arr.slice(0, maxLen).join(" ") + " ...";
      }
      return arr.join(" ");
    }

    function isPrintableAscii(bytes) {
      if (!bytes || bytes.length === 0) return false;
      let printable = 0;
      for (const b of bytes) {
        if (b === 0) continue;
        if (b >= 32 && b <= 126) printable++;
      }
      return printable > 0 && printable / bytes.length > 0.6;
    }

    function decodeAscii(bytes) {
      let s = "";
      for (const b of bytes) {
        if (b === 0) break;
        s += String.fromCharCode(b);
      }
      return s;
    }

    function encodeAsciiFixed(str, len) {
      const arr = new Uint8Array(len);
      for (let i = 0; i < Math.min(str.length, len); i++) {
        arr[i] = str.charCodeAt(i) & 0xFF;
      }
      return arr;
    }

    function parseRecords(buffer) {
      const view = new DataView(buffer);
      const out = [];
      let offset = 0;

      while (offset + 4 <= view.byteLength) {
        const id = view.getUint16(offset, true);
        const len = view.getUint16(offset + 2, true);
        const valueOffset = offset + 4;
        const end = valueOffset + len;

        if (end > view.byteLength) {
          out.push({
            index: out.length,
            offset,
            id,
            len,
            type: "truncated",
            value: null,
            raw: new Uint8Array(buffer.slice(valueOffset)),
            display: "[обрезанная запись]"
          });
          break;
        }

        const raw = new Uint8Array(buffer.slice(valueOffset, end));
        let type = "bytes";
        let value = null;
        let display = "";

        if (len === 8) {
          const num = view.getFloat64(valueOffset, true);
          if (Number.isFinite(num)) {
            type = "double";
            value = num;
            display = String(num);
          } else {
            type = "bytes";
            display = bytesToHex(raw);
          }
        } else if (isPrintableAscii(raw)) {
          type = "string";
          value = decodeAscii(raw);
          display = value;
        } else {
          type = "bytes";
          display = bytesToHex(raw);
        }

        out.push({
          index: out.length,
          offset,
          id,
          len,
          type,
          value,
          raw,
          changed: false,
          display
        });

        offset = end;
      }

      return out;
    }

    function refreshStatus() {
      if (!records.length) {
        statusEl.textContent = "Загрузите файл .PR1";
        return;
      }
      const changedCount = records.filter(r => r.changed).length;
      statusEl.innerHTML =
        `Записей: <b>${records.length}</b>. ` +
        `Изменено: <b>${changedCount}</b>. ` +
        (changedCount ? `<span class="warn">Есть несохранённые изменения</span>` : `<span class="ok">Изменений нет</span>`);
    }

    function renderTable(filter = "") {
      tbody.innerHTML = "";
      const q = filter.trim().toLowerCase();

      for (const rec of records) {
        const idHex = "0x" + rec.id.toString(16).toUpperCase().padStart(4, "0");
        const searchable = [
          rec.index,
          rec.offset,
          idHex,
          rec.id,
          rec.len,
          rec.type,
          rec.display || "",
          bytesToHex(rec.raw, 9999)
        ].join(" ").toLowerCase();

        if (q && !searchable.includes(q)) continue;

        const tr = document.createElement("tr");
        if (rec.changed) tr.classList.add("row-changed");

        tr.innerHTML = `
          <td class="cell-mono">${rec.index}</td>
          <td class="cell-mono">0x${rec.offset.toString(16).toUpperCase()}</td>
          <td class="cell-mono">${idHex}</td>
          <td class="cell-mono">${rec.id}</td>
          <td class="cell-mono">${rec.len}</td>
          <td>${rec.type}</td>
          <td></td>
          <td class="readonly-bytes">${bytesToHex(rec.raw)}</td>
        `;

        const valueTd = tr.children[6];

        if (rec.type === "double") {
          const input = document.createElement("input");
          input.type = "text";
          input.className = "editable";
          input.value = rec.value;
          input.addEventListener("change", () => {
            const v = Number(input.value.replace(",", "."));
            if (!Number.isFinite(v)) {
              alert("Некорректное число");
              input.value = rec.value;
              return;
            }
            const view = new DataView(workingBuffer);
            view.setFloat64(rec.offset + 4, v, true);
            rec.value = v;
            rec.raw = new Uint8Array(workingBuffer.slice(rec.offset + 4, rec.offset + 4 + rec.len));
            rec.display = String(v);
            rec.changed = true;
            renderTable(searchInput.value);
            refreshStatus();
          });
          valueTd.appendChild(input);
        } else if (rec.type === "string") {
          const input = document.createElement("input");
          input.type = "text";
          input.className = "editable";
          input.value = rec.value;
          input.addEventListener("change", () => {
            const bytes = encodeAsciiFixed(input.value, rec.len);
            new Uint8Array(workingBuffer, rec.offset + 4, rec.len).set(bytes);
            rec.value = decodeAscii(bytes);
            rec.raw = new Uint8Array(workingBuffer.slice(rec.offset + 4, rec.offset + 4 + rec.len));
            rec.display = rec.value;
            rec.changed = true;
            renderTable(searchInput.value);
            refreshStatus();
          });
          valueTd.appendChild(input);
        } else {
          valueTd.textContent = rec.display;
        }

        tbody.appendChild(tr);
      }
    }

    fileInput.addEventListener("change", async (e) => {
      const file = e.target.files[0];
      if (!file) return;

      originalFileName = file.name;
      const buf = await file.arrayBuffer();
      originalBuffer = buf.slice(0);
      workingBuffer = buf.slice(0);
      records = parseRecords(workingBuffer);

      saveBtn.disabled = false;
      resetBtn.disabled = false;

      renderTable();
      refreshStatus();
    });

    searchInput.addEventListener("input", () => {
      renderTable(searchInput.value);
    });

    resetBtn.addEventListener("click", () => {
      if (!originalBuffer) return;
      workingBuffer = originalBuffer.slice(0);
      records = parseRecords(workingBuffer);
      renderTable(searchInput.value);
      refreshStatus();
    });

    saveBtn.addEventListener("click", () => {
      if (!workingBuffer) return;
      const blob = new Blob([workingBuffer], { type: "application/octet-stream" });
      const a = document.createElement("a");
      const dot = originalFileName.lastIndexOf(".");
      const outName = dot >= 0
        ? originalFileName.slice(0, dot) + "_edited" + originalFileName.slice(dot)
        : originalFileName + "_edited";
      a.href = URL.createObjectURL(blob);
      a.download = outName;
      a.click();
      URL.revokeObjectURL(a.href);
    });
  </script>
</body>
</html>
```

## Как пользоваться

1. Сохраните код в файл `pr1_editor.html`
2. Откройте его в браузере
3. Загрузите `.PR1`
4. В таблице:
   - поля типа `string` можно править как текст
   - поля типа `double` можно править как число
5. Нажмите **"Скачать изменённый файл"**

---

## Ограничения текущей версии

Сразу честно:

- она считает, что формат везде такой:
  `uint16 id + uint16 len + len bytes data`
- строки трактуются как ASCII
- редактируются только:
  - строки
  - `double` длиной 8 байт
- сложные блоки типа `04 01` длиной 260 байт будут показаны как `bytes`

---

## Что можно улучшить следующим шагом

Я могу сделать для вас **версию 2**, где будет:

- фильтр **только строковые поля**
- фильтр **только числа**
- редактирование **ID по известным именам**
- отдельная панель:
  - `DEK 265 CENTRAL IMAGE`
  - `349mm qudratic rep left-down`
  - все найденные текстовые параметры
- hex-preview выбранной записи
- сравнение двух `.PR1` файлов
- экспорт списка параметров в CSV

Если хотите, я следующим сообщением могу сразу сделать **более удобную HTML-версию с нормальным интерфейсом именно под ваши файлы**.

Да — вот готовая **HTML-страница сравнения двух `.PR1` файлов**.

Что она умеет:

- загружать **2 файла `.PR1`**;
- разбирать записи как:
  - `ID (uint16 little-endian)`
  - `LEN (uint16 little-endian)`
  - `VALUE (len bytes)`
- сравнивать записи по `ID`;
- показывать:
  - только изменившиеся,
  - только числа,
  - только строки,
  - все записи;
- искать по:
  - ID,
  - значению,
  - тексту;
- фильтровать числовые значения по диапазону;
- подсвечивать **похожие на размеры/координаты/скорости**;
- экспортировать таблицу отличий в CSV.

Сохраните как `pr1_compare.html` и откройте в браузере.

