    </div>

    <div class="status" id="status">Загрузите два файла и нажмите "Сравнить".</div>
    <div class="small">
      Разбор записей: <span class="mono">[id:uint16][len:uint16][value:len]</span>, little-endian.
    </div>
  </div>

  <div class="panel">
    <div class="row">
      <label>Показ:
        <select id="mode">
          <option value="changed">Только изменившиеся</option>
          <option value="all">Все</option>
          <option value="onlyNumbers">Только числа</option>
          <option value="onlyStrings">Только строки</option>
        </select>
      </label>

      <label>
        <input type="checkbox" id="onlySuspects" />
        Только похожие на полезные параметры
      </label>

      <label>
        <input type="checkbox" id="hideEqual" checked />
        Скрыть одинаковые
      </label>

      <label>
        <input type="checkbox" id="textDiffOnly" />
        Только изменившийся текст
      </label>
    </div>

    <div class="row">
      <label>Поиск:
        <input type="text" id="search" placeholder="ID, значение, строка..." />
      </label>

      <label>Число от:
        <input type="number" id="minVal" step="any" />
      </label>

      <label>до:
        <input type="number" id="maxVal" step="any" />
      </label>

      <button id="clearFiltersBtn">Сброс фильтров</button>
    </div>

    <div class="small">
      Подсказки:
      <span class="badge b-size">size</span> размеры/габариты,
      <span class="badge b-coord">coord</span> координаты/смещения,
      <span class="badge b-speed">speed/press</span> скорость/давление,
      <span class="badge b-text">text</span> текст.
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>ID hex</th>
        <th>ID dec</th>
        <th>Len A</th>
        <th>Len B</th>
        <th>Тип A</th>
        <th>Тип B</th>
        <th>Value A</th>
        <th>Value B</th>
        <th>Δ</th>
        <th>Метки</th>
        <th>Raw A</th>
        <th>Raw B</th>
      </tr>
    </thead>
    <tbody id="tbody"></tbody>
  </table>

  <script>
    const fileAInput = document.getElementById("fileA");
    const fileBInput = document.getElementById("fileB");
    const compareBtn = document.getElementById("compareBtn");
    const exportBtn = document.getElementById("exportBtn");
    const statusEl = document.getElementById("status");
    const tbody = document.getElementById("tbody");

    const modeEl = document.getElementById("mode");
    const onlySuspectsEl = document.getElementById("onlySuspects");
    const hideEqualEl = document.getElementById("hideEqual");
    const textDiffOnlyEl = document.getElementById("textDiffOnly");
    const searchEl = document.getElementById("search");
    const minValEl = document.getElementById("minVal");
    const maxValEl = document.getElementById("maxVal");
    const clearFiltersBtn = document.getElementById("clearFiltersBtn");

    let comparedRows = [];
    let fileAName = "";
    let fileBName = "";

    function hex(n, width = 4) {
      return "0x" + n.toString(16).toUpperCase().padStart(width, "0");
    }

    function bytesToHex(bytes, maxLen = 48) {
      const arr = Array.from(bytes).map(b => b.toString(16).padStart(2, "0").toUpperCase());
      return arr.length > maxLen ? arr.slice(0, maxLen).join(" ") + " ..." : arr.join(" ");
    }

    function isPrintableAscii(bytes) {
      if (!bytes || !bytes.length) return false;
      let printable = 0;
      for (const b of bytes) {
        if (b === 0) continue;
        if (b >= 32 && b <= 126) printable++;
      }
      return printable > 0 && printable / bytes.length > 0.6;
    }

    function decodeAscii(bytes) {
      let s = "";
      for (const b of bytes) {
        if (b === 0) break;
        s += String.fromCharCode(b);
      }
      return s;
    }

    function parsePR1(buffer) {
      const view = new DataView(buffer);
      const records = [];
      let offset = 0;

      while (offset + 4 <= view.byteLength) {
        const id = view.getUint16(offset, true);
        const len = view.getUint16(offset + 2, true);
        const valueOffset = offset + 4;
        const end = valueOffset + len;

        if (end > view.byteLength) {
          records.push({
            id,
            len,
            offset,
            type: "truncated",
            value: null,
            display: "[truncated]",
            raw: new Uint8Array(buffer.slice(valueOffset))
          });
          break;
        }

        const raw = new Uint8Array(buffer.slice(valueOffset, end));
        let type = "bytes";
        let value = null;
        let display = bytesToHex(raw);

        if (len === 8) {
          const num = view.getFloat64(valueOffset, true);
          if (Number.isFinite(num)) {
            type = "double";
            value = num;
            display = String(num);
          }
        } else if (isPrintableAscii(raw)) {
          type = "string";
          value = decodeAscii(raw);
          display = value;
        }

        records.push({
          id,
          len,
          offset,
          type,
          value,
          display,
          raw
        });

        offset = end;
      }

      return records;
    }

    function mapById(records) {
      const m = new Map();
      for (const r of records) {
        if (!m.has(r.id)) m.set(r.id, []);
        m.get(r.id).push(r);
      }
      return m;
    }

    function recordsEqual(a, b) {
      if (!a || !b) return false;
      if (a.len !== b.len) return false;
      if (a.type !== b.type) {
        if (!(a.type === "double" && b.type === "double")) return false;
      }

      if (a.raw.length !== b.raw.length) return false;
      for (let i = 0; i < a.raw.length; i++) {
        if (a.raw[i] !== b.raw[i]) return false;
      }
      return true;
    }

    function classify(recA, recB) {
      const tags = [];
      const rec = recB || recA;
      if (!rec) return tags;

      if (rec.type === "string") {
        tags.push("text");
      }

      const nums = [recA, recB]
        .filter(r => r && r.type === "double")
        .map(r => r.value);

      const any = nums.length ? nums[0] : null;
      const absVals = nums.map(v => Math.abs(v));

      if (absVals.some(v => v >= 20 && v <= 800)) {
        tags.push("size");
      }

      if (absVals.some(v => v <= 1000)) {
        tags.push("coord");
      }

      if (absVals.some(v => v >= 0 && v <= 120)) {
        tags.push("speed/press");
      }

      return [...new Set(tags)];
    }

    function compareRecords(recordsA, recordsB) {
      const mapA = mapById(recordsA);
      const mapB = mapById(recordsB);

      const allIds = new Set([...mapA.keys(), ...mapB.keys()]);
      const rows = [];

      for (const id of Array.from(allIds).sort((a, b) => a - b)) {
        const arrA = mapA.get(id) || [];
        const arrB = mapB.get(id) || [];
        const count = Math.max(arrA.length, arrB.length);

        for (let i = 0; i < count; i++) {
          const a = arrA[i] || null;
          const b = arrB[i] || null;

          const equal = a && b ? recordsEqual(a, b) : false;
          let delta = "";

          if (a && b && a.type === "double" && b.type === "double") {
            delta = String(b.value - a.value);
          }

          const tags = classify(a, b);

          rows.push({
            id,
            a,
            b,
            equal,
            delta,
            tags
          });
        }
      }

      return rows;
    }

    function tagsHtml(tags) {
      return tags.map(t => {
        let cls = "b-text";
        if (t === "size") cls = "b-size";
        else if (t === "coord") cls = "b-coord";
        else if (t === "speed/press") cls = "b-speed";
        return `<span class="badge ${cls}">${t}</span>`;
      }).join("");
    }

    function render() {
      tbody.innerHTML = "";
      const mode = modeEl.value;
      const q = searchEl.value.trim().toLowerCase();
      const onlySuspects = onlySuspectsEl.checked;
      const hideEqual = hideEqualEl.checked;
      const textDiffOnly = textDiffOnlyEl.checked;
      const minVal = minValEl.value === "" ? null : Number(minValEl.value);
      const maxVal = maxValEl.value === "" ? null : Number(maxValEl.value);

      let shown = 0;

      comparedRows.forEach((row, index) => {
        const a = row.a;
        const b = row.b;

        if (hideEqual && row.equal) return;
        if (mode === "changed" && row.equal) return;
        if (mode === "onlyNumbers") {
          const ok = (a && a.type === "double") || (b && b.type === "double");
          if (!ok) return;
        }
        if (mode === "onlyStrings") {
          const ok = (a && a.type === "string") || (b && b.type === "string");
          if (!ok) return;
        }
        if (onlySuspects && row.tags.length === 0) return;
        if (textDiffOnly) {
          const ok = a && b && a.type === "string" && b.type === "string" && !row.equal;
          if (!ok) return;
        }

        const numbers = [a, b].filter(r => r && r.type === "double").map(r => r.value);
        if (minVal !== null || maxVal !== null) {
          const pass = numbers.some(v =>
            (minVal === null || v >= minVal) &&
            (maxVal === null || v <= maxVal)
          );
          if (!pass) return;
        }

        const hay = [
          hex(row.id),
          row.id,
          a ? a.display : "",
          b ? b.display : "",
          a ? bytesToHex(a.raw, 9999) : "",
          b ? bytesToHex(b.raw, 9999) : "",
          row.tags.join(" ")
        ].join(" ").toLowerCase();

        if (q && !hay.includes(q)) return;

        const tr = document.createElement("tr");
        if (!row.equal) tr.classList.add("changed");
        if (row.tags.includes("size")) tr.classList.add("suspect-size");
        else if (row.tags.includes("coord")) tr.classList.add("suspect-coord");
        else if (row.tags.includes("speed/press")) tr.classList.add("suspect-speed");

        tr.innerHTML = `
          <td class="mono">${index + 1}</td>
          <td class="mono">${hex(row.id)}</td>
          <td class="mono">${row.id}</td>
          <td class="mono">${a ? a.len : ""}</td>
          <td class="mono">${b ? b.len : ""}</td>
          <td>${a ? a.type : ""}</td>
          <td>${b ? b.type : ""}</td>
          <td>${a ? escapeHtml(a.display) : '<span class="warn">[нет]</span>'}</td>
          <td>${b ? escapeHtml(b.display) : '<span class="warn">[нет]</span>'}</td>
          <td class="mono">${escapeHtml(row.delta)}</td>
          <td>${tagsHtml(row.tags)}</td>
          <td class="raw mono">${a ? bytesToHex(a.raw) : ""}</td>
          <td class="raw mono">${b ? bytesToHex(b.raw) : ""}</td>
        `;

        tbody.appendChild(tr);
        shown++;
      });

      statusEl.innerHTML = `Сравнение: <b>${escapeHtml(fileAName)}</b> ↔ <b>${escapeHtml(fileBName)}</b>. Показано строк: <b>${shown}</b>. Всего сравнений: <b>${comparedRows.length}</b>.`;
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;");
    }

    async function readFile(file) {
      return await file.arrayBuffer();
    }

    compareBtn.addEventListener("click", async () => {
      const fa = fileAInput.files[0];
      const fb = fileBInput.files[0];

      if (!fa || !fb) {
        alert("Нужно выбрать оба файла.");
        return;
      }

      fileAName = fa.name;
      fileBName = fb.name;

      const [bufA, bufB] = await Promise.all([readFile(fa), readFile(fb)]);
      const recA = parsePR1(bufA);
      const recB = parsePR1(bufB);

      comparedRows = compareRecords(recA, recB);
      exportBtn.disabled = false;
      render();
    });

    [
      modeEl,
      onlySuspectsEl,
      hideEqualEl,
      textDiffOnlyEl,
      searchEl,
      minValEl,
      maxValEl
    ].forEach(el => el.addEventListener("input", render));

    clearFiltersBtn.addEventListener("click", () => {
      modeEl.value = "changed";
      onlySuspectsEl.checked = false;
      hideEqualEl.checked = true;
      textDiffOnlyEl.checked = false;
      searchEl.value = "";
      minValEl.value = "";
      maxValEl.value = "";
      render();
    });

    exportBtn.addEventListener("click", () => {
      const rows = [];
      rows.push([
        "id_hex", "id_dec",
        "len_a", "len_b",
        "type_a", "type_b",
        "value_a", "value_b",
        "delta", "tags"
      ]);

      const mode = modeEl.value;
      const q = searchEl.value.trim().toLowerCase();
      const onlySuspects = onlySuspectsEl.checked;
      const hideEqual = hideEqualEl.checked;
      const textDiffOnly = textDiffOnlyEl.checked;
      const minVal = minValEl.value === "" ? null : Number(minValEl.value);
      const maxVal = maxValEl.value === "" ? null : Number(maxValEl.value);

      for (const row of comparedRows) {
        const a = row.a;
        const b = row.b;

        if (hideEqual && row.equal) continue;
        if (mode === "changed" && row.equal) continue;
        if (mode === "onlyNumbers") {
          const ok = (a && a.type === "double") || (b && b.type === "double");
          if (!ok) continue;
        }
        if (mode === "onlyStrings") {
          const ok = (a && a.type === "string") || (b && b.type === "string");
          if (!ok) continue;
        }
        if (onlySuspects && row.tags.length === 0) continue;
        if (textDiffOnly) {
          const ok = a && b && a.type === "string" && b.type === "string" && !row.equal;
          if (!ok) continue;
        }

        const numbers = [a, b].filter(r => r && r.type === "double").map(r => r.value);
        if (minVal !== null || maxVal !== null) {
          const pass = numbers.some(v =>
            (minVal === null || v >= minVal) &&
            (maxVal === null || v <= maxVal)
          );
          if (!pass) continue;
        }

        const hay = [
          hex(row.id),
          row.id,
          a ? a.display : "",
          b ? b.display : "",
          row.tags.join(" ")
        ].join(" ").toLowerCase();

        if (q && !hay.includes(q)) continue;

        rows.push([
          hex(row.id),
          row.id,
          a ? a.len : "",
          b ? b.len : "",
          a ? a.type : "",
          b ? b.type : "",
          a ? a.display : "",
          b ? b.display : "",
          row.delta,
          row.tags.join("|")
        ]);
      }

      const csv = rows.map(r =>
        r.map(v => `"${String(v).replaceAll('"', '""')}"`).join(",")
      ).join("\n");

      const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "pr1_compare.csv";
      a.click();
      URL.revokeObjectURL(a.href);
    });
  </script>
</body>
</html>
```

## Как лучше использовать

Сделайте несколько сравнений:

1. **Base vs SizeChanged**
   - меняете только размеры платы

2. **Base vs FiducialsChanged**
   - меняете только координаты реперов

3. **Base vs SpeedChanged**
   - меняете только скорость ракеля

4. **Base vs PressureChanged**
   - меняете только давление

Потом в этой странице:

- включаете **"Только изменившиеся"**
- включаете диапазоны, например:
  - размеры: `20 .. 800`
  - pressure: `0 .. 50`
  - speed: `1 .. 200`

Так вы быстро увидите кандидатов по ID.

---

## Что, скорее всего, стоит искать первым

По вашему дампу я бы первым делом проверял ID около таких значений:

- `0x0064`
- `0x0069`
- `0x006E`
- `0x0022`
- `0x002E`
- `0x0C23`
- `0x0C24`
- `0x0C25`
- `0x0C2F`

Но это пока только кандидаты.

---

## Что можно сделать следующим шагом

После того как вы найдете нужные ID, я могу сделать вторую страницу:

- загружаете **один шаблонный `.PR1`**
- вводите:
  - ширину платы
  - высоту платы
  - X/Y реперов
  - скорость
  - давление
  - комментарий
- нажимаете **Скачать готовый PR1**

Если хотите, после ваших первых сравнений я помогу превратить найденные `ID` в **удобный редактор конкретных параметров**.

Да — нужно делать **не просто diff**, а **diff с группировкой зависимостей**.  
То есть страница должна не только показывать “что изменилось”, но и помогать понять:

- **основной параметр**
- **его производные**
- **дубли в других секциях**
- **похожие изменения по той же дельте**

И да, если `строка 23` — это половина длины, а `55` и `371` — дубли того же смысла в других блоках, то это как раз типичная схема бинарного проекта:
- основное значение,
- предрасчитанный центр,
- копия в другом подблоке,
- копия для визуализации/камеры/рабочей зоны.

## Ответ на главный вопрос

> Как учесть все изменения, если при изменении длины и ширины меняются многие параметры?

Правильный путь такой:

### Не редактировать “только 2 строки”
А построить **карту зависимостей**:

- `Board X`:
  - основной ID
  - половина X
  - возможно рабочая зона X
  - дубли X в других секциях
- `Board Y`:
  - основной ID
  - половина Y
  - рабочая зона Y
  - дубли Y
- `Thickness`:
  - основной ID
  - возможно зазоры/высоты/clearance
- и так далее

То есть у вас в итоге будет не:
- “длина = одна строка”

а:
- “длина = группа строк”

Это нормально.

---

## Что должна уметь новая страница

Я сделал для вас **v2-концепцию**, в которой есть:

### 1. Встроенная карта известных параметров
Уже предзаполнены:
- `0x000A` → `Board Y`
- `0x000B` → `Board X`
- `0x000C` → `Board Thickness`

И можно будет добавлять новые.

### 2. Пометка “зависимостей”
Страница будет подсвечивать:
- **same-delta-as-X**
- **same-delta-as-Y**
- **same-delta-as-thickness**
- **half-of-X**
- **half-of-Y**

### 3. Комментарии к ID
Можно будет вручную написать:
- `0x0023 = Center X`
- `0x0037 = Center X duplicate`
- `0x0173 = Center X duplicate 2`

### 4. Сохранение карты параметров
В JSON:
- имя
- группа
- комментарий
- формула/смысл

### 5. Фильтры
Показывать:
- только известные
- только неизвестные
- только связанные с X
- только связанные с Y
- только связанные с thickness
- только строки
- только числа
- только изменившиеся

