        <label><input type="checkbox" id="hideEqual" checked> Скрыть одинаковые</label>
        <label><input type="checkbox" id="onlyKnown"> Только известные</label>
        <label><input type="checkbox" id="onlyUnknown"> Только неизвестные</label>
      </div>

      <div class="row">
        <label><input type="checkbox" id="onlyXRel"> Только связанные с X</label>
        <label><input type="checkbox" id="onlyYRel"> Только связанные с Y</label>
        <label><input type="checkbox" id="onlyTRel"> Только связанные с Thickness</label>
      </div>

      <div class="row">
        <label><input type="checkbox" id="onlyHalf"> Только half-of</label>
        <label><input type="checkbox" id="onlyDup"> Только duplicate/close</label>
        <label><input type="checkbox" id="onlyFlagLike"> Только flag/enum-like</label>
        <label><input type="checkbox" id="onlyStructural"> Только structural-change</label>
      </div>

      <div class="row">
        <label>Общий поиск:
          <input type="text" id="search" placeholder="ID, Len, Value, текст, Raw, метка...">
        </label>
      </div>

      <div class="row">
        <label>Value A:
          <input type="text" id="valueASearch" placeholder="например 159">
        </label>
        <label>Value B:
          <input type="text" id="valueBSearch" placeholder="например 160">
        </label>
      </div>

      <div class="row">
        <label>Число от:
          <input type="number" id="minVal" step="any">
        </label>
        <label>до:
          <input type="number" id="maxVal" step="any">
        </label>
      </div>

      <div class="row">
        <label>Len:
          <input type="number" id="lenFilter" step="1" placeholder="1,2,4,8">
        </label>
        <button id="clearFiltersBtn">Сбросить фильтры</button>
      </div>

      <div class="help-block small">
        <b>Как помечать направление печати:</b><br>
        Если параметр меняет не одно значение, а группу/перестановку блоков, назначайте всем связанным строкам ручные метки:
        <span class="mono">direction</span>,
        <span class="mono">direction-group</span>,
        <span class="mono">forward-backward</span>,
        <span class="mono">swap-block</span>.<br>
        Тогда позже в генераторе можно будет реализовать не одиночное поле, а сценарий переключения группы.
      </div>
    </div>

    <div class="box">
      <h3>Карта параметров</h3>
      <div class="row">
        <button id="exportMapBtn">Экспорт карты JSON</button>
        <label>Импорт карты JSON:
          <input type="file" id="importMapInput">
        </label>
      </div>
      <div class="row">
        <input type="text" id="globalCustomTag" placeholder="Новая пользовательская метка">
      </div>
      <textarea id="mapPreview" readonly></textarea>
    </div>
  </div>

  <h2>Сравнение по ID</h2>
  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>ID hex</th>
        <th>ID dec</th>
        <th>Имя</th>
        <th>Комментарий</th>
        <th>Len A</th>
        <th>Len B</th>
        <th>Тип</th>
        <th>Value A</th>
        <th>Value B</th>
        <th>Δ</th>
        <th>Метки</th>
        <th>Raw A</th>
        <th>Raw B</th>
        <th>Назначить / изменить</th>
      </tr>
    </thead>
    <tbody id="tbody"></tbody>
  </table>

  <h2>Structural differences</h2>
  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>Index A</th>
        <th>Offset A</th>
        <th>ID A</th>
        <th>Value A</th>
        <th>Index B</th>
        <th>Offset B</th>
        <th>ID B</th>
        <th>Value B</th>
        <th>Признак</th>
      </tr>
    </thead>
    <tbody id="structBody"></tbody>
  </table>

  <script>
    const knownMap = {
      "0x000A": { name:"Board Y", group:"board_size", comment:"Ширина платы Y", manualTags:[] },
      "0x000B": { name:"Board X", group:"board_size", comment:"Длина платы X", manualTags:[] },
      "0x000C": { name:"Board Thickness", group:"board_thickness", comment:"Толщина платы", manualTags:[] }
    };

    let comparedRows = [];
    let structuralRows = [];
    let fileAName = "";
    let fileBName = "";

    const $ = id => document.getElementById(id);

    function hex(n, width=4){ return "0x" + n.toString(16).toUpperCase().padStart(width,"0"); }
    function escapeHtml(str){
      return String(str ?? "")
        .replaceAll("&","&amp;")
        .replaceAll("<","&lt;")
        .replaceAll(">","&gt;");
    }
    function bytesToHex(bytes, maxLen=48){
      const arr = Array.from(bytes).map(b => b.toString(16).padStart(2,"0").toUpperCase());
      return arr.length > maxLen ? arr.slice(0,maxLen).join(" ") + " ..." : arr.join(" ");
    }
    function isPrintableAscii(bytes){
      if (!bytes || !bytes.length) return false;
      let printable = 0;
      for (const b of bytes){
        if (b === 0) continue;
        if (b >= 32 && b <= 126) printable++;
      }
      return printable > 0 && printable / bytes.length > 0.6;
    }
    function decodeAscii(bytes){
      let s = "";
      for (const b of bytes){
        if (b === 0) break;
        s += String.fromCharCode(b);
      }
      return s;
    }
    function readIntLE(bytes){
      let val = 0;
      for (let i=0;i<bytes.length;i++) val += bytes[i] * (256 ** i);
      return val;
    }
    function nearlyEqual(a,b,eps=1e-9){
      return Number.isFinite(a) && Number.isFinite(b) && Math.abs(a-b) < eps;
    }
    function recordsEqual(a,b){
      if (!a || !b) return false;
      if (a.len !== b.len) return false;
      if (a.raw.length !== b.raw.length) return false;
      for (let i=0;i<a.raw.length;i++) if (a.raw[i] !== b.raw[i]) return false;
      return true;
    }
    function getKnownEntry(idHex){
      if (!knownMap[idHex]) knownMap[idHex] = { name:"", group:"", comment:"", manualTags:[] };
      if (!Array.isArray(knownMap[idHex].manualTags)) knownMap[idHex].manualTags = [];
      return knownMap[idHex];
    }
    function updateMapPreview(){
      $("mapPreview").value = JSON.stringify(knownMap, null, 2);
    }
    function toggleManualTag(idHex, tagName){
      const entry = getKnownEntry(idHex);
      const arr = entry.manualTags;
      const idx = arr.indexOf(tagName);
      if (idx >= 0) arr.splice(idx,1);
      else arr.push(tagName);
      updateMapPreview();
      render();
    }

    function parsePR1(buffer){
      const view = new DataView(buffer);
      const records = [];
      let offset = 0;
      let index = 0;

      while (offset + 4 <= view.byteLength){
        const id = view.getUint16(offset, true);
        const len = view.getUint16(offset + 2, true);
        const valueOffset = offset + 4;
        const end = valueOffset + len;

        if (end > view.byteLength){
          records.push({
            index, id, len, offset, type:"truncated", value:null,
            display:"[truncated]", raw:new Uint8Array(buffer.slice(valueOffset))
          });
          break;
        }

        const raw = new Uint8Array(buffer.slice(valueOffset, end));
        let type = "bytes";
        let value = null;
        let display = bytesToHex(raw);

        if (len === 8){
          const num = view.getFloat64(valueOffset, true);
          if (Number.isFinite(num)){
            type = "double";
            value = num;
            display = String(num);
          }
        } else if (isPrintableAscii(raw)){
          type = "string";
          value = decodeAscii(raw);
          display = value;
        } else if (len === 1 || len === 2 || len === 4){
          type = "bytes";
          value = readIntLE(raw);
          display = `int? ${value}`;
        }

        records.push({ index, id, len, offset, type, value, display, raw });
        offset = end;
        index++;
      }
      return records;
    }

    function mapById(records){
      const m = new Map();
      for (const r of records){
        if (!m.has(r.id)) m.set(r.id, []);
        m.get(r.id).push(r);
      }
      return m;
    }

    function isFlagLike(a,b){
      const recs = [a,b].filter(Boolean);
      if (!recs.length) return false;
      return recs.some(r => {
        if (![1,2,4].includes(r.len)) return false;
        if (r.type === "string") return false;
        const iv = Number(r.value);
        return Number.isFinite(iv) && iv >= 0 && iv <= 16;
      });
    }

    function classify(a,b,deltas){
      const tags = [];
      const rec = b || a;
      const idHex = hex(rec.id);
      const known = knownMap[idHex];

      if (known && (known.name || known.comment || (known.manualTags || []).length)) tags.push("known");
      if (rec.type === "string") tags.push("text");
      if (rec.type === "double") tags.push("number");
      if (rec.type === "bytes") tags.push("bytes");
      if (isFlagLike(a,b)) tags.push("flag/enum-like");

      const nums = [a,b].filter(r => r && r.type === "double").map(r => r.value);
      const absVals = nums.map(v => Math.abs(v));

      if (a && b && a.type === "double" && b.type === "double"){
        const d = b.value - a.value;
        if (nearlyEqual(d, deltas.x)) tags.push("same-delta-X");
        if (nearlyEqual(d, deltas.y)) tags.push("same-delta-Y");
        if (nearlyEqual(d, deltas.t)) tags.push("same-delta-thickness");
        if (nearlyEqual(b.value, deltas.currentX / 2)) tags.push("half-of-X");
        if (nearlyEqual(b.value, deltas.currentY / 2)) tags.push("half-of-Y");

        if (
          nearlyEqual(b.value, deltas.currentX) ||
          nearlyEqual(b.value, deltas.currentY) ||
          nearlyEqual(b.value, deltas.currentT) ||
          nearlyEqual(b.value, deltas.currentX / 2) ||
          nearlyEqual(b.value, deltas.currentY / 2)
        ) tags.push("duplicate/close");
      }

      if (absVals.some(v => v >= 20 && v <= 800)) tags.push("size");
      if (absVals.some(v => v <= 1000)) tags.push("coord");
      if (absVals.some(v => v >= 0 && v <= 120)) tags.push("speed/press");

      for (const mt of (known?.manualTags || [])) tags.push(`custom:${mt}`);
      return [...new Set(tags)];
    }

    function compareRecords(recordsA, recordsB){
      const mapA = mapById(recordsA);
      const mapB = mapById(recordsB);
      const allIds = new Set([...mapA.keys(), ...mapB.keys()]);
      const rows = [];

      const xA = (mapA.get(0x000B) || [])[0]?.value ?? null;
      const xB = (mapB.get(0x000B) || [])[0]?.value ?? null;
      const yA = (mapA.get(0x000A) || [])[0]?.value ?? null;
      const yB = (mapB.get(0x000A) || [])[0]?.value ?? null;
      const tA = (mapA.get(0x000C) || [])[0]?.value ?? null;
      const tB = (mapB.get(0x000C) || [])[0]?.value ?? null;

      const deltas = {
        x: (xA !== null && xB !== null) ? (xB - xA) : NaN,
        y: (yA !== null && yB !== null) ? (yB - yA) : NaN,
        t: (tA !== null && tB !== null) ? (tB - tA) : NaN,
        currentX: xB ?? xA ?? NaN,
        currentY: yB ?? yA ?? NaN,
        currentT: tB ?? tA ?? NaN
      };

      for (const id of Array.from(allIds).sort((a,b)=>a-b)){
        const arrA = mapA.get(id) || [];
        const arrB = mapB.get(id) || [];
        const count = Math.max(arrA.length, arrB.length);

        for (let i=0;i<count;i++){
          const a = arrA[i] || null;
          const b = arrB[i] || null;
          const equal = a && b ? recordsEqual(a,b) : false;
          const delta = (a && b && a.type === "double" && b.type === "double") ? (b.value - a.value) : "";
          const tags = classify(a,b,deltas);
          rows.push({ id, a, b, equal, delta, tags });
        }
      }
      return rows;
    }

    function buildStructuralDiff(recordsA, recordsB){
      const max = Math.max(recordsA.length, recordsB.length);
      const out = [];

      for (let i=0;i<max;i++){
        const a = recordsA[i] || null;
        const b = recordsB[i] || null;
        if (!a && !b) continue;

        let marker = "";
        if (!a || !b) {
          marker = "insert/delete";
        } else if (a.id !== b.id) {
          marker = "structural-change";
          const nextA = recordsA[i+1] || null;
          const nextB = recordsB[i+1] || null;
          if (nextA && nextB && a.id === nextB.id && b.id === nextA.id) {
            marker = "swap-candidate";
          }
        } else if (!recordsEqual(a,b)) {
          marker = "value-change";
        }

        if (marker) {
          out.push({
            indexA: a?.index ?? "",
            offsetA: a ? hex(a.offset, 8) : "",
            idA: a ? hex(a.id) : "",
            valueA: a?.display ?? "",
            indexB: b?.index ?? "",
            offsetB: b ? hex(b.offset, 8) : "",
            idB: b ? hex(b.id) : "",
            valueB: b?.display ?? "",
            marker
          });
        }
      }
      return out;
    }

    function badgeClass(tag){
      if (tag === "known") return "b-known";
      if (tag === "same-delta-X") return "b-x";
      if (tag === "same-delta-Y") return "b-y";
      if (tag === "same-delta-thickness") return "b-z";
      if (tag.startsWith("half-of")) return "b-half";
      if (tag === "duplicate/close") return "b-dup";
      if (tag === "text") return "b-text";
      if (tag === "number") return "b-num";
      if (tag === "bytes") return "b-bytes";
      if (tag === "flag/enum-like") return "b-flag";
      if (tag === "structural-change" || tag === "swap-candidate") return "b-struct";
      if (tag.startsWith("custom:")) return "b-custom";
      if (tag === "size") return "b-known";
      if (tag === "coord") return "b-y";
      if (tag === "speed/press") return "b-z";
      return "b-custom";
    }

    function renderTagControls(idHex, manualTags){
      const baseManual = [
        "x-related","y-related","thickness-related","center","fiducial","speed","pressure",
        "direction","direction-group","forward-backward","swap-block","auto","on/off"
      ];
      const globalCustom = $("globalCustomTag").value.trim();
      const tags = [...new Set([...baseManual, ...(globalCustom ? [globalCustom] : []), ...(manualTags || [])])];
      return tags.map(tag => {
        const active = (manualTags || []).includes(tag);
        return `<span class="badge ${badgeClass("custom:"+tag)} ${active ? "" : "off"} manual-tag" data-id="${idHex}" data-tag="${escapeHtml(tag)}">${escapeHtml(tag)}</span>`;
      }).join("");
    }

    function renderAutoTags(tags){
      return tags.map(tag => `<span class="badge ${badgeClass(tag)} static">${escapeHtml(tag)}</span>`).join("");
    }

    function buildSearchHay(row, known){
      const a = row.a, b = row.b;
      return [
        hex(row.id), row.id, known?.name || "", known?.comment || "",
        a?.len || "", b?.len || "", a?.type || b?.type || "",
        a?.display || "", b?.display || "", row.delta,
        bytesToHex(a?.raw || new Uint8Array(), 9999),
        bytesToHex(b?.raw || new Uint8Array(), 9999),
        row.tags.join(" "), ...(known?.manualTags || [])
      ].join(" ").toLowerCase();
    }

    function render(){
      $("tbody").innerHTML = "";
      $("structBody").innerHTML = "";

      const mode = $("mode").value;
      const hideEqual = $("hideEqual").checked;
      const onlyKnown = $("onlyKnown").checked;
      const onlyUnknown = $("onlyUnknown").checked;
      const onlyXRel = $("onlyXRel").checked;
      const onlyYRel = $("onlyYRel").checked;
      const onlyTRel = $("onlyTRel").checked;
      const onlyHalf = $("onlyHalf").checked;
      const onlyDup = $("onlyDup").checked;
      const onlyFlagLike = $("onlyFlagLike").checked;
      const onlyStructural = $("onlyStructural").checked;
      const q = $("search").value.trim().toLowerCase();
      const valueAQuery = $("valueASearch").value.trim().toLowerCase();
      const valueBQuery = $("valueBSearch").value.trim().toLowerCase();
      const minVal = $("minVal").value === "" ? null : Number($("minVal").value);
      const maxVal = $("maxVal").value === "" ? null : Number($("maxVal").value);
      const lenFilter = $("lenFilter").value === "" ? null : Number($("lenFilter").value);

      let shown = 0;

      for (let index=0; index<comparedRows.length; index++){
        const row = comparedRows[index];
        const a = row.a;
        const b = row.b;
        const idHex = hex(row.id);
        const known = getKnownEntry(idHex);
        const type = a?.type || b?.type || "";
        const autoTags = row.tags.filter(t => !t.startsWith("custom:"));
        const manualTags = known.manualTags || [];

        if (hideEqual && row.equal) continue;
        if (mode === "changed" && row.equal) continue;
        if (mode === "onlyNumbers" && type !== "double") continue;
        if (mode === "onlyStrings" && type !== "string") continue;
        if (mode === "onlyBytes" && type !== "bytes") continue;

        const isKnown = !!(known.name || known.comment || manualTags.length);
        if (onlyKnown && !isKnown) continue;
        if (onlyUnknown && isKnown) continue;
        if (onlyXRel && !autoTags.includes("same-delta-X") && !manualTags.includes("x-related")) continue;
        if (onlyYRel && !autoTags.includes("same-delta-Y") && !manualTags.includes("y-related")) continue;
        if (onlyTRel && !autoTags.includes("same-delta-thickness") && !manualTags.includes("thickness-related")) continue;
        if (onlyHalf && !autoTags.some(t => t.startsWith("half-of"))) continue;
        if (onlyDup && !autoTags.includes("duplicate/close")) continue;
        if (onlyFlagLike && !autoTags.includes("flag/enum-like")) continue;

        const nums = [a,b].filter(r => r && r.type === "double").map(r => r.value);
        if (minVal !== null || maxVal !== null) {
          const pass = nums.some(v => (minVal === null || v >= minVal) && (maxVal === null || v <= maxVal));
          if (!pass) continue;
        }

        if (lenFilter !== null){
          const la = a?.len ?? null;
          const lb = b?.len ?? null;
          if (la !== lenFilter && lb !== lenFilter) continue;
        }

        const hay = buildSearchHay(row, known);
        if (q && !hay.includes(q)) continue;

        const valueAText = String(a?.display || "").toLowerCase();
        const valueBText = String(b?.display || "").toLowerCase();
        if (valueAQuery && !valueAText.includes(valueAQuery)) continue;
        if (valueBQuery && !valueBText.includes(valueBQuery)) continue;

        if (onlyStructural) {
          const structHas = structuralRows.some(s => s.idA === idHex || s.idB === idHex);
          if (!structHas) continue;
        }

        const tr = document.createElement("tr");
        if (!row.equal) tr.classList.add("changed");
        if (isKnown) tr.classList.add("known");

        tr.innerHTML = `
          <td class="mono">${index + 1}</td>
          <td class="mono">${idHex}</td>
          <td class="mono">${row.id}</td>
          <td>${escapeHtml(known.name || "")}</td>
          <td>${escapeHtml(known.comment || "")}</td>
          <td class="mono">${a ? a.len : ""}</td>
          <td class="mono">${b ? b.len : ""}</td>
          <td>${escapeHtml(type)}</td>
          <td>${a ? escapeHtml(a.display) : '<span class="small">[нет]</span>'}</td>
          <td>${b ? escapeHtml(b.display) : '<span class="small">[нет]</span>'}</td>
          <td class="mono">${escapeHtml(String(row.delta))}</td>
          <td>
            <div>${renderAutoTags(autoTags)}</div>
            <div style="margin-top:6px">${renderTagControls(idHex, manualTags)}</div>
          </td>
          <td class="raw mono">${a ? bytesToHex(a.raw) : ""}</td>
          <td class="raw mono">${b ? bytesToHex(b.raw) : ""}</td>
          <td>
            <div class="assign-wrap">
              <input type="text" id="name_${row.id}_${index}" placeholder="Имя" value="${escapeHtml(known.name || "")}">
              <input type="text" id="comment_${row.id}_${index}" placeholder="Комментарий" value="${escapeHtml(known.comment || "")}">
              <button class="saveKnownBtn" data-id="${idHex}" data-index="${index}">Сохранить</button>
            </div>
          </td>
        `;
        $("tbody").appendChild(tr);
        shown++;
      }

      structuralRows.forEach((r, i) => {
        const tr = document.createElement("tr");
        tr.classList.add("structural");
        tr.innerHTML = `
          <td class="mono">${i + 1}</td>
          <td class="mono">${escapeHtml(String(r.indexA))}</td>
          <td class="mono">${escapeHtml(r.offsetA)}</td>
          <td class="mono">${escapeHtml(r.idA)}</td>
          <td>${escapeHtml(r.valueA)}</td>
          <td class="mono">${escapeHtml(String(r.indexB))}</td>
          <td class="mono">${escapeHtml(r.offsetB)}</td>
          <td class="mono">${escapeHtml(r.idB)}</td>
          <td>${escapeHtml(r.valueB)}</td>
          <td><span class="badge static ${badgeClass(r.marker)}">${escapeHtml(r.marker)}</span></td>
        `;
        $("structBody").appendChild(tr);
      });

      $("status").innerHTML =
        `Сравнение: <b>${escapeHtml(fileAName)}</b> ↔ <b>${escapeHtml(fileBName)}</b>. ` +
        `Показано по ID: <b>${shown}</b>. Structural rows: <b>${structuralRows.length}</b>.`;

      bindDynamicControls();
      updateMapPreview();
    }

    function bindDynamicControls(){
      document.querySelectorAll(".saveKnownBtn").forEach(btn => {
        btn.onclick = () => {
          const idHex = btn.dataset.id;
          const idx = btn.dataset.index;
          const decId = parseInt(idHex,16);
          const name = document.getElementById(`name_${decId}_${idx}`).value.trim();
          const comment = document.getElementById(`comment_${decId}_${idx}`).value.trim();
          const entry = getKnownEntry(idHex);
          entry.name = name;
          entry.comment = comment;
          render();
        };
      });

      document.querySelectorAll(".manual-tag").forEach(el => {
        el.onclick = () => {
          const idHex = el.dataset.id;
          const tag = el.dataset.tag;
          toggleManualTag(idHex, tag);
        };
      });
    }

    async function readFile(file){ return await file.arrayBuffer(); }

    $("compareBtn").addEventListener("click", async () => {
      const fa = $("fileA").files[0];
      const fb = $("fileB").files[0];
      if (!fa || !fb){ alert("Нужно выбрать оба файла."); return; }

      fileAName = fa.name;
      fileBName = fb.name;

      const [bufA, bufB] = await Promise.all([readFile(fa), readFile(fb)]);
      const recA = parsePR1(bufA);
      const recB = parsePR1(bufB);

      comparedRows = compareRecords(recA, recB);
      structuralRows = buildStructuralDiff(recA, recB);

      $("exportCsvBtn").disabled = false;
      render();
    });

    [
      "mode","hideEqual","onlyKnown","onlyUnknown","onlyXRel","onlyYRel","onlyTRel",
      "onlyHalf","onlyDup","onlyFlagLike","onlyStructural",
      "search","valueASearch","valueBSearch","minVal","maxVal","lenFilter","globalCustomTag"
    ].forEach(id => $(id).addEventListener("input", render));

    $("clearFiltersBtn").addEventListener("click", () => {
      $("mode").value = "changed";
      $("hideEqual").checked = true;
      $("onlyKnown").checked = false;
      $("onlyUnknown").checked = false;
      $("onlyXRel").checked = false;
      $("onlyYRel").checked = false;
      $("onlyTRel").checked = false;
      $("onlyHalf").checked = false;
      $("onlyDup").checked = false;
      $("onlyFlagLike").checked = false;
      $("onlyStructural").checked = false;
      $("search").value = "";
      $("valueASearch").value = "";
      $("valueBSearch").value = "";
      $("minVal").value = "";
      $("maxVal").value = "";
      $("lenFilter").value = "";
      render();
    });

    $("exportCsvBtn").addEventListener("click", () => {
      const rows = [[
        "id_hex","id_dec","name","comment","len_a","len_b","type","value_a","value_b","delta","auto_tags","manual_tags"
      ]];
      for (const row of comparedRows){
        const idHex = hex(row.id);
        const known = getKnownEntry(idHex);
        rows.push([
          idHex,row.id,known.name || "",known.comment || "",
          row.a?.len || "",row.b?.len || "",
          row.a?.type || row.b?.type || "",
          row.a?.display || "",row.b?.display || "",
          row.delta,row.tags.join("|"),(known.manualTags || []).join("|")
        ]);
      }
      const csv = rows.map(r => r.map(v => `"${String(v).replaceAll('"','""')}"`).join(",")).join("\n");
      const blob = new Blob([csv], { type:"text/csv;charset=utf-8;" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "pr1_compare_structural.csv";
      a.click();
      URL.revokeObjectURL(a.href);
    });

    $("exportMapBtn").addEventListener("click", () => {
      const blob = new Blob([JSON.stringify(knownMap, null, 2)], { type:"application/json" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "pr1_known_map.json";
      a.click();
      URL.revokeObjectURL(a.href);
    });

    $("importMapInput").addEventListener("change", async (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const text = await file.text();
      try{
        const parsed = JSON.parse(text);
        for (const k of Object.keys(parsed)){
          knownMap[k] = parsed[k];
          if (!Array.isArray(knownMap[k].manualTags)) knownMap[k].manualTags = [];
        }
        render();
      } catch(err){
        alert("Ошибка JSON: " + err.message);
      }
    });

    updateMapPreview();
  </script>
</body>
