    </div>
  </div>

  <h2>Блоки отличий</h2>
  <table>
    <thead>
      <tr>
        <th>#</th>
        <th>Offset start</th>
        <th>Offset end</th>
        <th>Size</th>
        <th>ASCII/UTF hints</th>
        <th>Numeric hints</th>
        <th>Hex A</th>
        <th>Hex B</th>
      </tr>
    </thead>
    <tbody id="diffBody"></tbody>
  </table>

  <h2>Подробный просмотр блока</h2>
  <div class="two-col">
    <div class="box">
      <h3>Файл A</h3>
      <div id="detailA" class="hexbox">Выберите блок отличий.</div>
    </div>
    <div class="box">
      <h3>Файл B</h3>
      <div id="detailB" class="hexbox">Выберите блок отличий.</div>
    </div>
  </div>

  <script>
    let fileNameA = "";
    let fileNameB = "";
    let bytesA = null;
    let bytesB = null;
    let diffBlocks = [];

    const $ = id => document.getElementById(id);

    function hex(n, width=8){
      return "0x" + n.toString(16).toUpperCase().padStart(width, "0");
    }

    function bytesToHex(arr, start=0, end=arr.length){
      const out = [];
      for(let i=start;i<end;i++){
        out.push(arr[i].toString(16).padStart(2,"0").toUpperCase());
      }
      return out.join(" ");
    }

    function bytesToAscii(arr, start=0, end=arr.length){
      let s = "";
      for(let i=start;i<end;i++){
        const b = arr[i];
        s += (b >= 32 && b <= 126) ? String.fromCharCode(b) : ".";
      }
      return s;
    }

    function escapeHtml(str){
      return String(str ?? "")
        .replaceAll("&","&amp;")
        .replaceAll("<","&lt;")
        .replaceAll(">","&gt;");
    }

    function extractAsciiStrings(arr, minLen=4){
      const result = [];
      let cur = "";
      let start = 0;
      for(let i=0;i<arr.length;i++){
        const b = arr[i];
        if(b >= 32 && b <= 126){
          if(cur.length === 0) start = i;
          cur += String.fromCharCode(b);
        } else {
          if(cur.length >= minLen){
            result.push(`${hex(start)}  ASCII  ${cur}`);
          }
          cur = "";
        }
      }
      if(cur.length >= minLen){
        result.push(`${hex(start)}  ASCII  ${cur}`);
      }
      return result;
    }

    function extractUtf16LeStrings(arr, minLen=4){
      const result = [];
      let i = 0;
      while(i < arr.length - 1){
        let chars = [];
        let start = i;
        let j = i;
        while(j < arr.length - 1){
          const c1 = arr[j];
          const c2 = arr[j+1];
          if(c2 === 0 && c1 >= 32 && c1 <= 126){
            chars.push(String.fromCharCode(c1));
            j += 2;
          } else {
            break;
          }
        }
        if(chars.length >= minLen){
          result.push(`${hex(start)}  UTF16LE  ${chars.join("")}`);
          i = j;
        } else {
          i += 1;
        }
      }
      return result;
    }

    function getUint16LE(arr, off){
      if(off + 1 >= arr.length) return null;
      return arr[off] | (arr[off+1] << 8);
    }

    function getUint32LE(arr, off){
      if(off + 3 >= arr.length) return null;
      return (arr[off]) | (arr[off+1] << 8) | (arr[off+2] << 16) | (arr[off+3] << 24 >>> 0);
    }

    function getFloat64LE(arr, off){
      if(off + 7 >= arr.length) return null;
      const buf = arr.slice(off, off + 8);
      const dv = new DataView(buf.buffer, buf.byteOffset, 8);
      const v = dv.getFloat64(0, true);
      return Number.isFinite(v) ? v : null;
    }

    function hasPrintable(arr, start, end){
      for(let i=start;i<end;i++){
        if(arr[i] >= 32 && arr[i] <= 126) return true;
      }
      return false;
    }

    function textHints(arr, start, end){
      const slice = arr.slice(start, end);
      const ascii = extractAsciiStrings(slice, 4).slice(0, 4);
      const utf16 = extractUtf16LeStrings(slice, 4).slice(0, 4);
      return [...ascii, ...utf16].join(" | ");
    }

    function numericHints(arr, start, end){
      const hints = [];
      const limit = Math.min(end, start + 24);

      for(let off = start; off < limit; off++){
        const u16 = getUint16LE(arr, off);
        const u32 = getUint32LE(arr, off);
        const f64 = getFloat64LE(arr, off);

        if(u16 !== null && u16 > 0 && u16 < 5000){
          hints.push(`${hex(off)} u16=${u16}`);
        }
        if(u32 !== null && u32 > 0 && u32 < 1000000){
          hints.push(`${hex(off)} u32=${u32}`);
        }
        if(f64 !== null && Math.abs(f64) > 0 && Math.abs(f64) < 100000){
          const rounded = Math.round(f64 * 1000) / 1000;
          if(Math.abs(rounded) > 0.000001){
            hints.push(`${hex(off)} f64=${rounded}`);
          }
        }
      }

      return [...new Set(hints)].slice(0, 8).join(" | ");
    }

    function buildDiffBlocks(a, b){
      const maxLen = Math.max(a.length, b.length);
      const minBlockSize = Number($("minBlockSize").value) || 1;
      const blocks = [];
      let inBlock = false;
      let blockStart = 0;

      for(let i=0;i<maxLen;i++){
        const ba = i < a.length ? a[i] : null;
        const bb = i < b.length ? b[i] : null;
        const diff = ba !== bb;

        if(diff && !inBlock){
          inBlock = true;
          blockStart = i;
        } else if(!diff && inBlock){
          const blockEnd = i - 1;
          if(blockEnd - blockStart + 1 >= minBlockSize){
            blocks.push({ start:blockStart, end:blockEnd });
          }
          inBlock = false;
        }
      }

      if(inBlock){
        const blockEnd = maxLen - 1;
        if(blockEnd - blockStart + 1 >= minBlockSize){
          blocks.push({ start:blockStart, end:blockEnd });
        }
      }

      return blocks;
    }

    function renderBlocks(){
      const tbody = $("diffBody");
      tbody.innerHTML = "";

      const q = $("search").value.trim().toLowerCase();
      const win = Number($("windowSize").value) || 32;
      const onlyPrintable = $("showOnlyPrintable").checked;
      const onlyNumeric = $("showOnlyNumericHints").checked;

      let shown = 0;

      diffBlocks.forEach((blk, idx) => {
        const viewStart = Math.max(0, blk.start - win);
        const viewEndA = Math.min(bytesA.length, blk.end + win + 1);
        const viewEndB = Math.min(bytesB.length, blk.end + win + 1);

        const hintA = textHints(bytesA, viewStart, viewEndA);
        const hintB = textHints(bytesB, viewStart, viewEndB);
        const hintText = [hintA, hintB].filter(Boolean).join(" || ");

        const numA = numericHints(bytesA, viewStart, viewEndA);
        const numB = numericHints(bytesB, viewStart, viewEndB);
        const numText = [numA, numB].filter(Boolean).join(" || ");

        const hexA = bytesToHex(bytesA, viewStart, viewEndA);
        const hexB = bytesToHex(bytesB, viewStart, viewEndB);

        const hay = [
          hex(blk.start),
          hex(blk.end),
          blk.end - blk.start + 1,
          hintText,
          numText,
          hexA,
          hexB,
          bytesToAscii(bytesA, viewStart, viewEndA),
          bytesToAscii(bytesB, viewStart, viewEndB)
        ].join(" ").toLowerCase();

        if(q && !hay.includes(q)) return;
        if(onlyPrintable && !hintText) return;
        if(onlyNumeric && !numText) return;

        const tr = document.createElement("tr");
        tr.className = "diff-row";
        tr.innerHTML = `
          <td class="mono">${idx + 1}</td>
          <td class="mono">${hex(blk.start)}</td>
          <td class="mono">${hex(blk.end)}</td>
          <td class="mono">${blk.end - blk.start + 1}</td>
          <td>${escapeHtml(hintText)}</td>
          <td>${escapeHtml(numText)}</td>
          <td class="mono">${escapeHtml(shorten(hexA, 160))}</td>
          <td class="mono">${escapeHtml(shorten(hexB, 160))}</td>
        `;
        tr.style.cursor = "pointer";
        tr.onclick = () => showDetail(blk);
        tbody.appendChild(tr);
        shown++;
      });

      $("status").innerHTML =
        `Сравнение: <b>${escapeHtml(fileNameA)}</b> ↔ <b>${escapeHtml(fileNameB)}</b>. ` +
        `Найдено блоков отличий: <b>${diffBlocks.length}</b>. Показано: <b>${shown}</b>.`;
    }

    function shorten(s, n){
      return s.length > n ? s.slice(0, n) + " ..." : s;
    }

    function showDetail(blk){
      const win = Number($("windowSize").value) || 32;
      const start = Math.max(0, blk.start - win);
      const endA = Math.min(bytesA.length, blk.end + win + 1);
      const endB = Math.min(bytesB.length, blk.end + win + 1);

      $("detailA").innerHTML = formatDetailed(bytesA, start, endA, blk.start, blk.end);
      $("detailB").innerHTML = formatDetailed(bytesB, start, endB, blk.start, blk.end);
    }

    function formatDetailed(arr, start, end, diffStart, diffEnd){
      let out = "";
      const lineSize = 16;

      for(let off = start; off < end; off += lineSize){
        const lineEnd = Math.min(end, off + lineSize);
        let hexParts = [];
        let ascii = "";

        for(let i = off; i < lineEnd; i++){
          const hx = arr[i].toString(16).padStart(2,"0").toUpperCase();
          const inDiff = i >= diffStart && i <= diffEnd;
          hexParts.push(inDiff ? `<span class="mark">${hx}</span>` : hx);

          const ch = (arr[i] >= 32 && arr[i] <= 126) ? String.fromCharCode(arr[i]) : ".";
          ascii += inDiff ? `<span class="mark">${escapeHtml(ch)}</span>` : escapeHtml(ch);
        }

        const u16 = getUint16LE(arr, off);
        const u32 = getUint32LE(arr, off);
        const f64 = getFloat64LE(arr, off);
        let hints = [];
        if(u16 !== null) hints.push(`u16=${u16}`);
        if(u32 !== null) hints.push(`u32=${u32 >>> 0}`);
        if(f64 !== null && Math.abs(f64) > 0 && Math.abs(f64) < 1000000) {
          hints.push(`f64=${Math.round(f64 * 1000)/1000}`);
        }

        out += `<div><span class="mono">${hex(off)}:</span> ${hexParts.join(" ")} &nbsp;&nbsp; ${ascii} &nbsp;&nbsp; <span class="small">${escapeHtml(hints.join(" | "))}</span></div>`;
      }

      return out;
    }

    async function loadFile(file){
      const buf = await file.arrayBuffer();
      return new Uint8Array(buf);
    }

    $("analyzeBtn").addEventListener("click", async () => {
      const fa = $("fileA").files[0];
      const fb = $("fileB").files[0];
      if(!fa || !fb){
        alert("Нужно выбрать оба файла.");
        return;
      }

      fileNameA = fa.name;
      fileNameB = fb.name;

      bytesA = await loadFile(fa);
      bytesB = await loadFile(fb);

      diffBlocks = buildDiffBlocks(bytesA, bytesB);

      const stringsA = [
        ...extractAsciiStrings(bytesA, 4),
        ...extractUtf16LeStrings(bytesA, 4)
      ].slice(0, 300);

      const stringsB = [
        ...extractAsciiStrings(bytesB, 4),
        ...extractUtf16LeStrings(bytesB, 4)
      ].slice(0, 300);

      $("stringsA").value = stringsA.join("\n");
      $("stringsB").value = stringsB.join("\n");

      $("exportCsvBtn").disabled = false;
      renderBlocks();
    });

    $("refreshBtn").addEventListener("click", () => {
      if(!bytesA || !bytesB) return;
      diffBlocks = buildDiffBlocks(bytesA, bytesB);
      renderBlocks();
    });

    ["search","windowSize","minBlockSize","showOnlyPrintable","showOnlyNumericHints"].forEach(id => {
      $(id).addEventListener("input", () => {
        if(!bytesA || !bytesB) return;
        if(id === "minBlockSize"){
          diffBlocks = buildDiffBlocks(bytesA, bytesB);
        }
        renderBlocks();
      });
      $(id).addEventListener("change", () => {
        if(!bytesA || !bytesB) return;
        if(id === "minBlockSize"){
          diffBlocks = buildDiffBlocks(bytesA, bytesB);
        }
        renderBlocks();
      });
    });

    $("exportCsvBtn").addEventListener("click", () => {
      const rows = [["block_no","offset_start","offset_end","size","text_hints","numeric_hints"]];
      const win = Number($("windowSize").value) || 32;

      diffBlocks.forEach((blk, idx) => {
        const viewStart = Math.max(0, blk.start - win);
        const viewEndA = Math.min(bytesA.length, blk.end + win + 1);
        const viewEndB = Math.min(bytesB.length, blk.end + win + 1);

        const hintA = textHints(bytesA, viewStart, viewEndA);
        const hintB = textHints(bytesB, viewStart, viewEndB);
        const numA = numericHints(bytesA, viewStart, viewEndA);
        const numB = numericHints(bytesB, viewStart, viewEndB);

        rows.push([
          idx + 1,
          hex(blk.start),
          hex(blk.end),
          blk.end - blk.start + 1,
          [hintA, hintB].filter(Boolean).join(" || "),
          [numA, numB].filter(Boolean).join(" || ")
        ]);
      });

      const csv = rows.map(r =>
        r.map(v => `"${String(v).replaceAll('"','""')}"`).join(",")
      ).join("\n");

      const blob = new Blob([csv], { type:"text/csv;charset=utf-8;" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "isd_diff_blocks.csv";
      a.click();
      URL.revokeObjectURL(a.href);
    });
  </script>
</body>
</html>
```

