function showToast(message, type = "info") {
  const icons = {
    info: "info",
    success: "check-circle-2",
    error: "alert-circle",
    warn: "alert-triangle"
  };

  const el = document.createElement("div");
  el.className = "toast rounded-lg shadow-lg px-4 py-3 flex items-center gap-2.5 text-[12.5px] max-w-[320px]";
  el.style.background = "var(--surface)";
  el.style.border = "1px solid var(--border)";
  el.style.color = "var(--text)";
  el.innerHTML = `
    <i data-lucide="${icons[type]}" class="w-4 h-4 shrink-0" style="color:var(--accent)"></i>
    <span>${message}</span>
  `;

  document.getElementById("toastContainer").appendChild(el);
  lucide.createIcons();

  setTimeout(() => {
    el.style.opacity = "0";
    el.style.transition = "opacity .3s";
    setTimeout(() => el.remove(), 300);
  }, 3200);
}

/**
 * Устанавливает статус в левом блоке.
