/* ============================================================================
   7. ГРУППИРОВКА ПОЛЕЙ
   ----------------------------------------------------------------------------
   Здесь заложена архитектура для динамического построения формы из JSON-карты.
   Позже можно расширять правила группировки.
   ============================================================================ */

/**
 * Возвращает человекочитаемое название группы.
 */
function getGroupTitle(groupName) {
  const map = {
    dimensions: "Блок «Габариты»",
    fiducials: "Блок «Реперные знаки»",
    speeds: "Блок «Скорости»",
    pressures: "Блок «Давление»",
    directions: "Блок «Направления / режимы»",
    offsets: "Блок «Смещения / координаты»",
    custom: "Блок «Пользовательские параметры»"
  };

  return map[groupName] || `Блок «${groupName}»`;
}

/**
 * Возвращает CSS grid-классы для группы.
 * Это позволит красиво раскладывать группы по смыслу.
 */
function getGroupGridClass(groupName) {
  switch (groupName) {
    case "dimensions":
      return "grid grid-cols-1 md:grid-cols-3 gap-4";
    case "fiducials":
      return "grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4";
    case "speeds":
    case "pressures":
    case "offsets":
      return "grid grid-cols-1 md:grid-cols-3 gap-4";
    default:
      return "grid grid-cols-1 md:grid-cols-2 gap-4";
  }
}

/**
 * Группирует параметры по полю group.
 */
function groupParameters(parameterMap) {
  const grouped = {};

  Object.entries(parameterMap).forEach(([id, config]) => {
    const group = config.group || "custom";
    if (!grouped[group]) grouped[group] = [];
    grouped[group].push({ id, ...config });
  });

  return grouped;
}

/**
 * Создаёт HTML-поля для параметров из карты.
 */
function renderDynamicParameterGroups() {
  const container = document.getElementById("parameterGroupsContainer");
  const grouped = groupParameters(appState.parameterMap);

  container.innerHTML = "";

  Object.entries(grouped).forEach(([groupName, items]) => {
    const wrapper = document.createElement("div");
    wrapper.className = "param-group";

    const title = document.createElement("div");
    title.className = "param-group-title";
    title.textContent = getGroupTitle(groupName);

    const grid = document.createElement("div");
    grid.className = getGroupGridClass(groupName);

    items.forEach(item => {
      const fieldWrap = document.createElement("div");

      fieldWrap.innerHTML = `
        <p class="field-label mb-2">${escapeHtml(item.name || item.id)}</p>
        <input
          class="field-input dynamic-param-input"
          data-param-id="${escapeHtml(item.id)}"
          placeholder="${escapeHtml(item.comment || item.id)}"
        />
        <p class="helper-text mt-1">${escapeHtml(item.comment || "")}</p>
      `;

      grid.appendChild(fieldWrap);
    });

    wrapper.appendChild(title);
    wrapper.appendChild(grid);
    container.appendChild(wrapper);
  });

  bindDynamicParameterInputs();
  updateChangedFieldsCard();
}

/**
 * Привязывает обработчики к динамически созданным полям.
 * При вводе поле подсвечивается и помечается как изменённое.
 */
function bindDynamicParameterInputs() {
  const inputs = document.querySelectorAll(".dynamic-param-input");

  inputs.forEach(input => {
    input.addEventListener("input", () => {
      const id = input.dataset.paramId;
      const value = input.value;

      appState.parameterValues[id] = value;

      if (value.trim() !== "") {
        appState.changedFields.add(id);
        input.classList.add("is-dirty");
      } else {
        appState.changedFields.delete(id);
        input.classList.remove("is-dirty");
      }

      updateChangedFieldsCard();
      logAction(`Изменено поле ${id}`, value);
    });
  });
}

/* ============================================================================
   8. ПРОВЕРКА ДОСТУПНОСТИ ПРИНТЕРА / СЕТИ
   ----------------------------------------------------------------------------
   Сейчас это заглушка.
   В будущем здесь должна быть:
   - проверка существования сетевой папки
   - ping / доступность сервера
   - проверка чтения/записи
   ============================================================================ */

/**
 * Проверка доступности принтера / сетевой папки.
 */
async function checkPrinterAvailability() {
  logAction("Запущена проверка доступности принтера");
  setStatus("var(--accent)", true, "Проверка сети…", appState.serverPath);

  try {
    // -----------------------------------------------------------------------
    // ЗАГЛУШКА:
    // В реальной версии:
    // 1. Electron/Node: проверить доступность папки SERVER_PATH
    // 2. Или через backend запросить сервер
    // -----------------------------------------------------------------------
    await wait(700);

    // Для демонстрации случайный результат:
    const simulatedOnline = true;

    appState.printerOnline = simulatedOnline;

    if (simulatedOnline) {
      setStatus("var(--success)", false, "Принтер доступен", "Сетевая папка отвечает");
      showToast("Принтер / сетевая папка доступны", "success");
    } else {
      setStatus("var(--danger)", false, "Принтер недоступен", "Нет доступа к сетевой папке");
      showToast("Нет доступа к принтеру / сетевой папке", "error");
    }

    updatePrinterStatusCard();
    refreshAllCards();
  } catch (error) {
    console.error(error);
    appState.printerOnline = false;
    setStatus("var(--danger)", false, "Ошибка проверки", error.message);
    updatePrinterStatusCard();
    showToast("Ошибка проверки доступности принтера", "error");
  }
}

/* ============================================================================
   9. ГЕНЕРАЦИЯ ПРОЕКТА
   ----------------------------------------------------------------------------
   Здесь каркас основной бизнес-логики.
   Потом сюда будет подключена:
   - загрузка template.PR1 / template.ISD / template.pxf
   - подстановка параметров
   - проверка существования файлов
   - диалог перезаписи
   - запись локально и на сервер
   ============================================================================ */

/**
 * Основная функция генерации проекта.
 */
async function generateProject() {
  logAction("Нажата кнопка «Сохранить изменения» / генерация проекта");

  const boardName = document.getElementById("boardNameInput").value.trim();
  appState.boardName = boardName;
  updateProjectCard();

  // 1. Валидация
  if (!boardName) {
    showToast("Поле «Название платы» обязательно", "warn");
    logAction("Ошибка валидации: пустое название платы");
    return;
  }

  try {
    setStatus("var(--accent)", true, "Генерация проекта…", boardName);

    // 2. Имена итоговых файлов
    const finalPr1Name = `${boardName}.PR1`;
    const finalIsdName = `${boardName}.ISD`;
    const finalPxfName = `${boardName}.pxf`;

    logAction("Сформированы имена файлов", {
      finalPr1Name,
      finalIsdName,
      finalPxfName
    });

    // -----------------------------------------------------------------------
    // 3. Чтение шаблонов
    // В рабочей версии здесь будет:
    // - чтение LOCAL_PATH + TEMPLATE_PR1_NAME
    // - чтение LOCAL_PATH + TEMPLATE_ISD_NAME
    // - чтение LOCAL_PATH + TEMPLATE_PXF_NAME
    // -----------------------------------------------------------------------
    await wait(500);
    logAction("Шаблоны считаны (демо)");

    // -----------------------------------------------------------------------
    // 4. Генерация PR1
    // В рабочей версии:
    // - парсинг template.PR1
    // - подстановка appState.parameterValues
    // - сбор нового бинарного файла
    // -----------------------------------------------------------------------
    await wait(400);
    logAction("PR1 подготовлен на основе введённых параметров", appState.parameterValues);

    // -----------------------------------------------------------------------
    // 5. Контроль перезаписи
    // В рабочей версии:
    // - проверить наличие finalPr1Name / finalIsdName / finalPxfName
    //   в LOCAL_PATH и SERVER_PATH
    // - показать confirm
    // -----------------------------------------------------------------------
    const overwriteConfirmed = confirm(
      `Проверка перезаписи (демо).\n\n` +
      `Если такие файлы уже существуют, перезаписать?\n\n` +
      `${finalPr1Name}\n${finalIsdName}\n${finalPxfName}`
    );

    if (!overwriteConfirmed) {
      setStatus("var(--warning)", false, "Генерация отменена", "Пользователь отменил перезапись");
      logAction("Генерация отменена пользователем на этапе перезаписи");
      return;
    }

    // -----------------------------------------------------------------------
    // 6. Сохранение файлов
    // В рабочей версии:
    // - запись в LOCAL_PATH
    // - запись в SERVER_PATH
    // -----------------------------------------------------------------------
    await wait(600);
    logAction("Файлы сохранены (демо)", {
      localPath: appState.localPath,
      serverPath: appState.serverPath
    });

    // -----------------------------------------------------------------------
    // 7. История генерации
    // -----------------------------------------------------------------------
    const generationTime = new Date().toLocaleString("ru-RU");
    appState.lastGenerationTime = generationTime;
    appState.generationHistory.push({
      boardName,
      createdAt: generationTime,
      files: [finalPr1Name, finalIsdName, finalPxfName]
    });

    appendGenerationLog(
      `[${generationTime}] Создан проект: ${boardName}\n` +
      `  - ${finalPr1Name}\n` +
      `  - ${finalIsdName}\n` +
      `  - ${finalPxfName}`
    );

    refreshAllCards();
    setStatus("var(--success)", false, "Проект создан", boardName);
    showToast(`Проект ${boardName} успешно сформирован`, "success");
  } catch (error) {
    console.error(error);
    logAction("Ошибка генерации проекта", error);
    setStatus("var(--danger)", false, "Ошибка генерации", error.message);
    showToast("Ошибка генерации проекта", "error");
  }
}

