function bindEvents() {
  document.getElementById("themeToggle").addEventListener("click", toggleTheme);

  document.getElementById("printerStatusCard").addEventListener("click", checkPrinterAvailability);
  document.getElementById("checkPrinterBtn").addEventListener("click", checkPrinterAvailability);

  document.getElementById("generateBtn").addEventListener("click", generateProject);
  document.getElementById("resetFormBtn").addEventListener("click", resetForm);
  document.getElementById("openLocalFolderBtn").addEventListener("click", openLocalFolder);
  document.getElementById("openPrinterFilesBtn").addEventListener("click", openPrinterFiles);
