  .section-title{
    font-size:30px;
    font-weight:800;
    margin-bottom:18px;
    line-height:1.1;
  }

  .field-label{
    font-family:'JetBrains Mono',monospace;
    font-size:13px;
    letter-spacing:.08em;
    color:var(--muted);
    text-transform:uppercase;
    margin-bottom:8px;
    font-weight:600;
  }

  .field-input, .field-select, .field-textarea{
    width:100%;
    background:var(--surface-alt);
    border:1px solid var(--border);
    border-radius:10px;
    padding:12px 14px;
    font-size:16px;
    color:var(--text);
    transition:.15s ease;
  }

  .field-textarea{
    min-height:90px;
    resize:vertical;
  }

  .field-input:focus, .field-select:focus, .field-textarea:focus{
    outline:none;
    border-color:var(--accent);
    box-shadow:0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
  }

  .field-input.is-dirty, .field-select.is-dirty, .field-textarea.is-dirty{
    border-color:color-mix(in srgb, var(--accent) 70%, var(--border));
    background:color-mix(in srgb, var(--accent) 8%, var(--surface-alt));
  }

  .field-input:disabled{
    opacity:.65;
    cursor:not-allowed;
  }

  .ghost-btn, .solid-btn{
    display:flex;
    align-items:center;
    gap:8px;
    border-radius:10px;
    padding:12px 14px;
    font-size:15px;
    font-weight:600;
    transition:.15s ease;
  }

  .ghost-btn{
    border:1px solid var(--border);
    background:var(--surface-alt);
    color:var(--text);
  }

  .ghost-btn:hover{
    border-color:var(--accent);
    color:var(--accent);
    transform:translateY(-1px);
  }

  .solid-btn{
    background:var(--accent);
    color:var(--accent-fg);
    justify-content:center;
  }

  .solid-btn:hover{
    transform:translateY(-1px);
    opacity:.92;
  }

  .toggle-wrap{
    display:flex;
    gap:8px;
    background:var(--surface-alt);
    border:1px solid var(--border);
    border-radius:12px;
    padding:4px;
  }

  .toggle-btn{
    flex:1;
    border:none;
    border-radius:9px;
    padding:11px 12px;
    font-size:16px;
    font-weight:700;
    color:var(--muted);
    background:transparent;
