  <div class="hero-bg absolute inset-0 pointer-events-none"></div>
  <div class="relative max-w-[1550px] mx-auto px-5 lg:px-8 pt-8 pb-8">
    <div class="flex items-center justify-between gap-4 mb-7">
      <div class="breadcrumb">
        <span class="dot"></span>
        <span id="headerProjectName">создание-проекта-printer-asm</span>
        <span>·</span>
        <span>локальный режим</span>
        <span>·</span>
        <span id="todayLabel"></span>
      </div>

      <button id="themeToggle" class="ghost-btn">
        <i data-lucide="sun-moon" class="w-4 h-4"></i>
        Тема
      </button>
    </div>

    <h1 class="font-display font-extrabold text-[40px] leading-[1.08] tracking-tight max-w-4xl">
      Создание <span style="color:var(--accent)">проекта принтера ASM</span>
    </h1>

    <p class="mt-4 text-[16px] text-muted max-w-3xl">
      Генератор проекта на основе шаблонов PR1 / ISD / pxf.
    </p>

    <div class="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 mt-7">
      <button id="printerStatusCard" class="stat-card clickable text-left">
        <div class="stat-label">Статус принтера</div>
        <div class="mt-2"><span class="stat-num" id="statPrinterStatus" style="color:var(--danger)">offline</span></div>
        <div class="stat-cap" id="statPrinterStatusSub">не подключено</div>
      </button>

      <div class="stat-card">
        <div class="stat-label">Проект</div>
        <div class="mt-2"><span class="stat-num fit-project" id="statProjectName" style="font-size:32px;">—</span></div>
        <div class="stat-cap">название платы</div>
      </div>

      <div class="stat-card">
        <div class="stat-label">Поля</div>
        <div class="mt-2">
          <span class="stat-num" id="statChangedFields">0</span>
          <span style="font-size:16px;color:var(--muted)" id="statChangedFieldsTotal">/0</span>
        </div>
        <div class="stat-cap">изменено / доступно</div>
      </div>

      <div class="stat-card">
        <div class="stat-label">Последняя генерация</div>
        <div class="mt-2"><span class="stat-num" id="statLastGeneration" style="font-size:24px;">—</span></div>
        <div class="stat-cap">время</div>
      </div>
    </div>
  </div>
</header>

<div class="flex-1 max-w-[1550px] w-full mx-auto flex flex-col lg:flex-row">
  <aside class="lg:w-[390px] shrink-0 px-5 lg:px-8 py-8 lg:border-r border-border space-y-10">

    <section>
      <div class="eyebrow mb-4">/ 01 <span>Похожие проекты</span></div>
      <div class="hint-list" id="similarProjectsList">
        Начните вводить название проекта.
      </div>
      <div class="helper">
        Чтение реальной папки проектов подключается позже через Electron или backend.
      </div>
    </section>

    <section class="hair-t pt-8">
      <div class="eyebrow mb-4">/ 02 <span>Управление</span></div>
      <div class="space-y-2.5">
        <button id="generateBtn" class="solid-btn w-full">
          <i data-lucide="save" class="w-4 h-4"></i>
          Сохранить изменения
        </button>
        <button id="checkPrinterBtn" class="ghost-btn w-full">
          <i data-lucide="wifi" class="w-4 h-4"></i>
          Доступность принтера
        </button>
        <button id="openPrinterFilesBtn" class="ghost-btn w-full">
          <i data-lucide="folder-tree" class="w-4 h-4"></i>
          Файлы на принтере
        </button>
        <button id="resetFormBtn" class="ghost-btn w-full">
          <i data-lucide="rotate-ccw" class="w-4 h-4"></i>
          Сбросить форму
        </button>
      </div>
    </section>

    <section class="hair-t pt-8">
      <div class="eyebrow mb-4">/ 03 <span>Пути</span></div>
      <div class="space-y-4">
        <div>
          <div class="field-label">Локальная папка</div>
          <input class="field-input" value="c:\settings\Project_Printer_ASM\" />
        </div>
        <div>
          <div class="field-label">Папка сервера</div>
          <input class="field-input" value="\\server\common\Novozhilov\" />
        </div>
      </div>
    </section>
  </aside>

  <main class="flex-1 min-w-0 px-5 lg:px-8 py-8">
    <section>
      <div class="eyebrow mb-4">/ 04 <span>Генератор параметров</span></div>

      <div class="space-y-6">
        <div class="section-card p-5">
          <h2 class="section-title">Проект</h2>

          <div class="grid grid-cols-1 xl:grid-cols-2 gap-5">
            <div>
              <div class="field-label">Название платы *</div>
              <input id="boardNameInput" class="field-input" placeholder="NSFT080100.006_20200603_B" />
              <div class="helper">Используется в именах файлов .PR1 / .ISD / .pxf</div>
            </div>

            <div>
              <div class="field-label">Комментарий (макс. 32 символа)</div>
              <input id="commentInput" class="field-input" maxlength="32" placeholder="Автозаполнение + ваш текст" />
              <div class="helper">Начало заполняется автоматически по формуле: 270 + Board Y / 2</div>
            </div>
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Габариты платы</h2>

          <div class="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div>
              <div class="field-label">Board X</div>
              <input id="boardXInput" class="field-input tracked-input" data-id="0x000B" type="number" step="any" />
            </div>
            <div>
              <div class="field-label">Board Y</div>
              <input id="boardYInput" class="field-input tracked-input" data-id="0x000A" type="number" step="any" />
            </div>
            <div>
              <div class="field-label">Board Thickness</div>
              <input id="boardThicknessInput" class="field-input tracked-input" data-id="0x000C" type="number" step="any" />
            </div>
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Реперы</h2>

          <div class="mb-5">
            <div class="field-label">Количество реперных знаков</div>
            <div class="toggle-wrap" id="refCountToggle">
              <button class="toggle-btn active" data-value="2">2</button>
              <button class="toggle-btn" data-value="3">3</button>
            </div>
            <div class="helper">2 репера = 0x0032 → 0, 3 репера = 0x0032 → 1</div>
          </div>

          <div class="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div>
              <div class="field-label">REF1_X</div>
              <input id="ref1x" class="field-input tracked-input" data-id="0x0033" type="number" step="any" />
              <div class="field-subnote">Координата X первого репера</div>
            </div>
            <div>
              <div class="field-label">REF1_Y</div>
              <input id="ref1y" class="field-input tracked-input" data-id="0x0034" type="number" step="any" />
              <div class="field-subnote">Координата Y первого репера</div>
            </div>
            <div></div>

            <div>
              <div class="field-label">REF2_X</div>
              <input id="ref2x" class="field-input tracked-input" data-id="0x0035" type="number" step="any" />
              <div class="field-subnote">Координата X второго репера</div>
            </div>
            <div>
              <div class="field-label">REF2_Y</div>
              <input id="ref2y" class="field-input tracked-input" data-id="0x0036" type="number" step="any" />
              <div class="field-subnote">Координата Y второго репера</div>
            </div>
            <div></div>

            <div>
              <div class="field-label">REF3_X</div>
              <input id="ref3x" class="field-input tracked-input" data-id="0x0037" type="number" step="any" />
              <div class="field-subnote">Координата X третьего репера</div>
            </div>
            <div>
              <div class="field-label">REF3_Y</div>
              <input id="ref3y" class="field-input tracked-input" data-id="0x0038" type="number" step="any" />
              <div class="field-subnote">Координата Y третьего репера</div>
            </div>
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Позиционирование платы</h2>

          <div class="grid grid-cols-1 xl:grid-cols-2 gap-5 mb-5">
            <div>
              <div class="field-label">Board stop mode</div>
              <div class="toggle-wrap" id="boardStopModeToggle">
                <button class="toggle-btn active" data-value="0">Авто</button>
                <button class="toggle-btn" data-value="1">Вручную</button>
              </div>
            </div>

            <div>
              <div class="field-label">Side of the board</div>
              <div class="toggle-wrap" id="boardSideToggle">
                <button class="toggle-btn active" data-value="0">Top</button>
                <button class="toggle-btn" data-value="1">Bottom</button>
              </div>
            </div>
          </div>

          <div class="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div>
              <div class="field-label">Center Board X_0</div>
              <input id="centerBoardX0" class="field-input tracked-input" data-id="0x0046" type="number" step="any" />
              <div class="helper">Авто: Board X / 2. В ручном режиме можно изменить.</div>
            </div>

            <div>
              <div class="field-label">Stop Board Y</div>
              <input id="stopBoardY" class="field-input tracked-input" data-id="0x0047" type="number" step="any" />
              <div class="helper">Авто: 70% от Board Y, пока не изменено вручную.</div>
            </div>
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Печать</h2>

          <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5">
            <div>
              <div class="field-label">Front squeegee pressure</div>
              <input id="frontPressure" class="field-input tracked-input" data-id="0x0010" type="number" step="any" />
              <div class="field-subnote">Давление переднего ракеля</div>
            </div>

            <div>
              <div class="field-label">Rear squeegee pressure</div>
              <input id="rearPressure" class="field-input tracked-input" data-id="0x0011" type="number" step="any" />
              <div class="field-subnote">Давление заднего ракеля</div>
            </div>

            <div>
              <div class="field-label">Quantity of squeegee passes</div>
              <input id="squeegeePasses" class="field-input tracked-input" data-id="0x0015" type="number" step="1" />
              <div class="field-subnote">Количество проходов ракеля</div>
            </div>

            <div>
              <div class="field-label">Print Direction</div>
              <div class="toggle-wrap" id="printDirectionToggle">
                <button class="toggle-btn" data-value="A">Backward</button>
                <button class="toggle-btn active" data-value="B">Forward</button>
              </div>
              <div class="field-subnote">Направление печати</div>
            </div>
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Разделение</h2>

          <div class="grid grid-cols-1 md:grid-cols-2 gap-5">
            <div>
              <div class="field-label">Separation Rate</div>
              <input id="separationRate" class="field-input tracked-input" data-id="0x0013" type="number" step="any" />
            </div>
            <div>
              <div class="field-label">Separation distance</div>
              <input id="separationDistance" class="field-input tracked-input" data-id="0x2715" type="number" step="any" />
            </div>
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Паста и обслуживание</h2>

          <div class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5">
            <div>
              <div class="field-label">Quantity of paste stirrings</div>
              <input id="pasteStirrings" class="field-input tracked-input" data-id="0x0023" type="number" step="1" />
            </div>
            <div>
              <div class="field-label">Cleaning frequency</div>
              <input id="cleaningFrequency" class="field-input tracked-input" data-id="0x0028" type="number" step="1" />
            </div>
            <div>
              <div class="field-label">Mixing pressure</div>
              <input id="mixingPressure" class="field-input tracked-input" data-id="0x766C" type="number" step="any" />
            </div>
            <div>
              <div class="field-label">Paste mixing speed</div>
              <input id="mixingSpeed" class="field-input tracked-input" data-id="0x766D" type="number" step="any" />
            </div>
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Добавление нового поля</h2>

          <div class="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div>
              <div class="field-label">ID</div>
              <input id="newFieldId" class="field-input" placeholder="0x1234" />
            </div>
            <div>
              <div class="field-label">Имя</div>
              <input id="newFieldName" class="field-input" placeholder="Название поля" />
            </div>
            <div>
              <div class="field-label">Комментарий</div>
              <input id="newFieldComment" class="field-input" placeholder="Описание" />
            </div>
          </div>

          <div class="mt-5">
            <button id="addFieldBtn" class="solid-btn">
              <i data-lucide="plus-circle" class="w-4 h-4"></i>
              Добавить поле
            </button>
          </div>

          <div class="helper">
            Позже это поле должно автоматически дописываться в pr1_known_map.json.
          </div>
        </div>

        <div class="section-card p-5">
          <h2 class="section-title">Расширенные параметры</h2>

          <div class="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div>
              <div class="field-label">Center Board Minus</div>
              <input id="centerBoardMinus" class="field-input tracked-input" data-id="0x0020" type="number" step="any" />
            </div>
            <div>
              <div class="field-label">Center Board 3</div>
              <input id="centerBoard3" class="field-input tracked-input" data-id="0x0021" type="number" step="any" />
            </div>
            <div>
              <div class="field-label">Center Board</div>
              <input id="centerBoardCommon" class="field-input tracked-input" data-id="0x193E" type="number" step="any" />
            </div>
          </div>
        </div>
      </div>
    </section>
  </main>
</div>

<div id="toastContainer" class="fixed bottom-5 right-5 flex flex-col gap-2 z-50"></div>

<script>
const state = {
  theme: localStorage.getItem("asm-theme") || "dark",
  changedFields: new Set(),
  lastGenerationTime: null,
  printerOnline: false,
  values: {
    "0x0032": 0,
    "0x7613": 0,
    "0x765D": 0,
    printDirectionGroup: "B",
    "0x2710": ""
  },
  stopBoardYWasManuallyEdited: false,
  commentWasManuallyEdited: false
};

const demoProjects = [
  "nsft080100.003_20250908_T",
  "nsft080100.004_20250911_B",
  "nsft080100.006_20200603_B",
  "nsft080120.001_20241010_T",
  "nsft080130.002_20241115_B"
];

function $(id){ return document.getElementById(id); }

function showToast(message, type="info"){
  const icons = {
    info: "info",
    success: "check-circle-2",
    error: "alert-circle",
    warn: "alert-triangle"
  };
  const el = document.createElement("div");
  el.className = "toast rounded-lg shadow-lg px-4 py-3 flex items-center gap-2.5 text-[14px] max-w-[340px]";
  el.style.background = "var(--surface)";
  el.style.border = "1px solid var(--border)";
  el.style.color = "var(--text)";
  el.innerHTML = `<i data-lucide="${icons[type]}" class="w-4 h-4 shrink-0" style="color:var(--accent)"></i><span>${message}</span>`;
  $("toastContainer").appendChild(el);
  lucide.createIcons();
  setTimeout(() => {
    el.style.opacity = "0";
    el.style.transition = "opacity .3s";
    setTimeout(() => el.remove(), 300);
  }, 2600);
}

function setToday(){
  $("todayLabel").textContent = new Date().toLocaleDateString("ru-RU", {
    day:"numeric", month:"long", year:"numeric"
  });
}

function applyTheme(mode){
  document.documentElement.classList.toggle("light", mode === "light");
  state.theme = mode;
  localStorage.setItem("asm-theme", mode);
  setTimeout(fitStatTexts, 30);
}

function toggleTheme(){
  applyTheme(state.theme === "dark" ? "light" : "dark");
}

function updateProjectCard(){
  const name = $("boardNameInput").value.trim();
  $("statProjectName").textContent = name || "—";
  $("headerProjectName").textContent = name || "создание-проекта-printer-asm";
  fitStatTexts();
}

function updateChangedCounter(){
  const total = document.querySelectorAll(".tracked-input").length + 5;
  $("statChangedFields").textContent = state.changedFields.size;
  $("statChangedFieldsTotal").textContent = `/${total}`;
}

function setPrinterStatus(isOnline){
  state.printerOnline = isOnline;
  $("statPrinterStatus").textContent = isOnline ? "online" : "offline";
  $("statPrinterStatus").style.color = isOnline ? "var(--success)" : "var(--danger)";
  $("statPrinterStatusSub").textContent = isOnline ? "подключено" : "не подключено";
}

function setLastGenerationNow(){
  const time = new Date().toLocaleString("ru-RU");
  state.lastGenerationTime = time;
  $("statLastGeneration").textContent = time;
}

function markDirty(el, key){
  const hasValue = String(el.value).trim() !== "";
  if (hasValue) {
    el.classList.add("is-dirty");
    state.changedFields.add(key);
  } else {
    el.classList.remove("is-dirty");
    state.changedFields.delete(key);
  }
  updateChangedCounter();
}

function getNum(id){
  const v = parseFloat($(id).value);
  return Number.isFinite(v) ? v : null;
}

function updateCommentAutoPrefix(){
  const boardY = getNum("boardYInput");
  if (boardY === null) return;

  const autoPrefix = String(Math.round(270 + boardY / 2));
  const current = $("commentInput").value;

  if (!state.commentWasManuallyEdited || current.trim() === "") {
    $("commentInput").value = autoPrefix;
    state.values["0x2710"] = autoPrefix;
    markDirty($("commentInput"), "0x2710");
  }
}

function updateCenterBoardX0Auto(){
  const isAuto = state.values["0x7613"] === 0;
  const x = getNum("boardXInput");
  const input = $("centerBoardX0");

  if (isAuto) {
    input.disabled = true;
    if (x !== null) {
      const val = x / 2;
      input.value = String(val);
      state.values["0x0046"] = val;
      markDirty(input, "0x0046");
    }
  } else {
    input.disabled = false;
  }
}

function updateStopBoardYAuto(){
  if (state.stopBoardYWasManuallyEdited) return;
  const y = getNum("boardYInput");
  if (y === null) return;

  const val = Math.round((y * 0.70) * 1000) / 1000;
  $("stopBoardY").value = String(val);
  state.values["0x0047"] = val;
  markDirty($("stopBoardY"), "0x0047");
}

function updateRefFieldsByCount(){
  const isThree = state.values["refCount"] === 3;
  state.values["0x0032"] = isThree ? 1 : 0;

  $("ref3x").disabled = !isThree;
  $("ref3y").disabled = !isThree;

  if (!isThree) {
    $("ref3x").value = "";
    $("ref3y").value = "";
    $("ref3x").classList.remove("is-dirty");
    $("ref3y").classList.remove("is-dirty");
    state.changedFields.delete("0x0037");
    state.changedFields.delete("0x0038");
  }

  updateChangedCounter();
}

function setupToggle(containerId, stateKey, onChange=null){
  const wrap = $(containerId);
  const buttons = wrap.querySelectorAll(".toggle-btn");

  buttons.forEach(btn => {
    btn.addEventListener("click", () => {
      buttons.forEach(b => b.classList.remove("active"));
      btn.classList.add("active");

      const raw = btn.dataset.value;
      state.values[stateKey] = /^\d+$/.test(raw) ? Number(raw) : raw;
      state.changedFields.add(stateKey);
      updateChangedCounter();

      if (onChange) onChange();
    });
  });
}

function updateSimilarProjects(){
  const val = $("boardNameInput").value.trim().toLowerCase();
  const list = $("similarProjectsList");

  if (!val) {
    list.textContent = "Начните вводить название проекта.";
    return;
  }

  const match = val.match(/^nsft(\d{6,})/i);
  if (!match) {
    list.textContent = "Для поиска введите имя в формате nsft...";
    return;
  }

  const prefix = "nsft" + match[1].slice(0, 6);
  const found = demoProjects.filter(x => x.toLowerCase().startsWith(prefix));

  if (!found.length) {
    list.textContent = "Похожие проекты не найдены.";
    return;
  }

  list.innerHTML = found.map(x => `<div style="padding:5px 0">${x}</div>`).join("");
}

function fitTextElement(el, min=18, max=32){
  if (!el) return;
  el.style.fontSize = max + "px";
  let current = max;

  while (current > min && (el.scrollWidth > el.clientWidth || el.scrollHeight > el.clientHeight)) {
    current -= 1;
    el.style.fontSize = current + "px";
  }
}

function fitStatTexts(){
  const el = $("statProjectName");
  if (el) fitTextElement(el, 18, 32);
}

function checkPrinter(){
  setPrinterStatus(true);
  showToast("Проверка сети выполнена (демо)", "success");
}

function resetForm(){
  document.querySelectorAll(".tracked-input").forEach(input => {
    input.value = "";
    input.disabled = false;
    input.classList.remove("is-dirty");
  });

  $("boardNameInput").value = "";
  $("commentInput").value = "";
  $("newFieldId").value = "";
  $("newFieldName").value = "";
  $("newFieldComment").value = "";

  state.changedFields.clear();
  state.stopBoardYWasManuallyEdited = false;
  state.commentWasManuallyEdited = false;

  state.values["0x0032"] = 0;
  state.values["0x7613"] = 0;
  state.values["0x765D"] = 0;
  state.values["0x2710"] = "";
  state.values["refCount"] = 2;
  state.values.printDirectionGroup = "B";

  document.querySelectorAll("#refCountToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 0);
  });
  document.querySelectorAll("#boardStopModeToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 0);
  });
  document.querySelectorAll("#boardSideToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 0);
  });
  document.querySelectorAll("#printDirectionToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 1);
  });

  updateRefFieldsByCount();
  updateCenterBoardX0Auto();
  updateChangedCounter();
  updateProjectCard();
  updateSimilarProjects();
  fitStatTexts();
  showToast("Форма сброшена", "success");
}

function generateProject(){
  const boardName = $("boardNameInput").value.trim();
  if (!boardName) {
    showToast("Заполните Название платы", "warn");
    return;
  }

  setLastGenerationNow();

  const payload = {
    boardName,
    values: {
      "0x000B": $("boardXInput").value,
      "0x000A": $("boardYInput").value,
      "0x000C": $("boardThicknessInput").value,
      "0x2710": $("commentInput").value,
      "0x0032": state.values["0x0032"],
      "0x0033": $("ref1x").value,
      "0x0034": $("ref1y").value,
      "0x0035": $("ref2x").value,
      "0x0036": $("ref2y").value,
      "0x0037": $("ref3x").value,
      "0x0038": $("ref3y").value,
      "0x7613": state.values["0x7613"],
      "0x0046": $("centerBoardX0").value,
      "0x0047": $("stopBoardY").value,
      "0x765D": state.values["0x765D"],
      "0x0010": $("frontPressure").value,
      "0x0011": $("rearPressure").value,
      "0x0015": $("squeegeePasses").value,
      "0x0013": $("separationRate").value,
      "0x2715": $("separationDistance").value,
      "0x0023": $("pasteStirrings").value,
      "0x0028": $("cleaningFrequency").value,
      "0x766C": $("mixingPressure").value,
      "0x766D": $("mixingSpeed").value,
      "0x0020": $("centerBoardMinus").value,
      "0x0021": $("centerBoard3").value,
      "0x193E": $("centerBoardCommon").value,
      "printDirectionGroup": state.values.printDirectionGroup
    }
  };

  console.log("Готово к генерации:", payload);
  showToast("Данные собраны. Реальную запись файлов подключим следующим этапом.", "success");
}

function addNewField(){
  const id = $("newFieldId").value.trim();
  const name = $("newFieldName").value.trim();
  const comment = $("newFieldComment").value.trim();

  if (!id || !name) {
    showToast("Заполните ID и Имя", "warn");
    return;
  }

  console.log("Добавить в карту:", { id, name, comment });
  showToast(`Поле ${id} добавлено в список (демо)`, "success");
}

function bindTrackedInputs(){
  document.querySelectorAll(".tracked-input").forEach(input => {
    const key = input.dataset.id || input.id;

    input.addEventListener("input", () => {
      markDirty(input, key);
      state.values[key] = input.value;
    });
  });
}

function init(){
  applyTheme(state.theme);
  setToday();
  updateChangedCounter();
  setPrinterStatus(false);

  $("themeToggle").addEventListener("click", toggleTheme);
  $("checkPrinterBtn").addEventListener("click", checkPrinter);
  $("printerStatusCard").addEventListener("click", checkPrinter);
  $("resetFormBtn").addEventListener("click", resetForm);
  $("generateBtn").addEventListener("click", generateProject);
  $("addFieldBtn").addEventListener("click", addNewField);

  $("boardNameInput").addEventListener("input", () => {
    $("boardNameInput").classList.toggle("is-dirty", $("boardNameInput").value.trim() !== "");
    if ($("boardNameInput").value.trim() !== "") state.changedFields.add("boardName");
    else state.changedFields.delete("boardName");
    updateChangedCounter();
    updateProjectCard();
    updateSimilarProjects();
  });

  $("commentInput").addEventListener("input", () => {
    state.commentWasManuallyEdited = true;
    state.values["0x2710"] = $("commentInput").value;
    markDirty($("commentInput"), "0x2710");
  });

  $("boardXInput").addEventListener("input", () => {
    updateCenterBoardX0Auto();
  });

  $("boardYInput").addEventListener("input", () => {
    updateCommentAutoPrefix();
    updateStopBoardYAuto();
  });

  $("stopBoardY").addEventListener("input", () => {
    state.stopBoardYWasManuallyEdited = true;
  });

  setupToggle("refCountToggle", "refCount", updateRefFieldsByCount);
  setupToggle("boardStopModeToggle", "0x7613", updateCenterBoardX0Auto);
  setupToggle("boardSideToggle", "0x765D");
  setupToggle("printDirectionToggle", "printDirectionGroup");

  bindTrackedInputs();

  state.values["refCount"] = 2;
  updateRefFieldsByCount();
  updateCenterBoardX0Auto();
  updateSimilarProjects();

  lucide.createIcons();
  fitStatTexts();
  window.addEventListener("resize", fitStatTexts);
}

init();
</script>
</body>
</html>
