    color:var(--muted);
  }

  .stat-num{
    font-weight:800;
    font-size:32px;
    line-height:1.05;
  }

  .stat-num.fit-project{
    display:block;
    max-width:100%;
    overflow:hidden;
    word-break:break-word;
    hyphens:auto;
  }

  .stat-cap{
    font-size:13px;
    color:var(--muted);
    margin-top:5px;
  }

  .section-card{
    background:var(--surface);
    border:1px solid var(--border);
    border-radius:16px;
  }

  .section-title{
    font-size:26px;
    font-weight:800;
    margin-bottom:14px;
    line-height:1.08;
  }

  .field-label{
    font-family:'JetBrains Mono',monospace;
    font-size:13px;
    letter-spacing:.08em;
    color:var(--muted);
    text-transform:uppercase;
    margin-bottom:6px;
    font-weight:600;
  }

  .field-input, .field-select, .field-textarea{
    width:100%;
    background:var(--surface-alt);
    border:1px solid var(--border);
    border-radius:10px;
    padding:10px 12px;
    font-size:16px;
    color:var(--text);
    transition:.15s ease;
  }

  .field-textarea{
    min-height:78px;
    resize:vertical;
  }

  .field-input:focus, .field-select:focus, .field-textarea:focus{
    outline:none;
    border-color:var(--accent);
    box-shadow:0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
  }

  .field-input.is-dirty, .field-select.is-dirty, .field-textarea.is-dirty{
    border-color:color-mix(in srgb, var(--accent) 70%, var(--border));
    background:color-mix(in srgb, var(--accent) 8%, var(--surface-alt));
  }

  .field-input:disabled{
    opacity:.65;
    cursor:not-allowed;
  }

  .ghost-btn, .solid-btn{
    display:flex;
    align-items:center;
    gap:8px;
    border-radius:10px;
    padding:11px 13px;
    font-size:15px;
    font-weight:600;
    transition:.15s ease;
  }

  .ghost-btn{
    border:1px solid var(--border);
    background:var(--surface-alt);
    color:var(--text);
  }

  .ghost-btn:hover{
    border-color:var(--accent);
    color:var(--accent);
    transform:translateY(-1px);
  }

  .solid-btn{
    background:var(--accent);
    color:var(--accent-fg);
    justify-content:center;
  }

  .solid-btn:hover{
    transform:translateY(-1px);
    opacity:.92;
  }

  .toggle-wrap{
    display:flex;
    gap:6px;
    background:var(--surface-alt);
    border:1px solid var(--border);
    border-radius:12px;
    padding:3px;
  }

  .toggle-btn{
    flex:1;
    border:none;
    border-radius:8px;
    padding:7px 10px;
    font-size:14px;
    font-weight:700;
    color:var(--muted);
    background:transparent;
    transition:.15s ease;
  }

  .toggle-btn.active{
    background:color-mix(in srgb, var(--accent) 18%, transparent);
    color:var(--text);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent);
  }

  .toggle-wrap.compact{
    width:50%;
    min-width:180px;
  }

  .helper{
    font-size:13px;
    color:var(--muted);
    line-height:1.45;
    margin-top:5px;
  }

  .hint-list{
    background:var(--surface-alt);
    border:1px solid var(--border);
    border-radius:12px;
    padding:10px 12px;
    font-size:14px;
    color:var(--muted);
    max-height:180px;
    overflow:auto;
  }

  .toast{
    animation:slide-in .22s ease-out;
  }

  @keyframes slide-in{
    from{ transform:translateY(8px); opacity:0; }
    to{ transform:translateY(0); opacity:1; }
  }
</style>
