<div id="toastContainer" class="fixed bottom-5 right-5 flex flex-col gap-2 z-50"></div>

<script>
const state = {
  theme: localStorage.getItem("asm-theme") || "dark",
  changedFields: new Set(),
  lastGenerationTime: null,
  printerOnline: false,
  values: {
    "0x0032": 0,
    "0x7613": 0,
    "0x765D": 0,
    printDirectionGroup: "B"
  },
  stopBoardYWasManuallyEdited: false,
  commentWasManuallyEdited: false
};

const demoProjects = [
  "nsft080100.003_20250908_T",
  "nsft080100.004_20250911_B",
  "nsft080100.006_20200603_B",
  "nsft080120.001_20241010_T",
  "nsft080130.002_20241115_B"
];

function $(id){ return document.getElementById(id); }

function showToast(message, type="info"){
  const icons = {
    info: "info",
    success: "check-circle-2",
    error: "alert-circle",
    warn: "alert-triangle"
  };
  const el = document.createElement("div");
  el.className = "toast rounded-lg shadow-lg px-4 py-3 flex items-center gap-2.5 text-[14px] max-w-[340px]";
  el.style.background = "var(--surface)";
  el.style.border = "1px solid var(--border)";
  el.style.color = "var(--text)";
  el.innerHTML = `<i data-lucide="${icons[type]}" class="w-4 h-4 shrink-0" style="color:var(--accent)"></i><span>${message}</span>`;
  $("toastContainer").appendChild(el);
  lucide.createIcons();
  setTimeout(() => {
    el.style.opacity = "0";
    el.style.transition = "opacity .3s";
    setTimeout(() => el.remove(), 300);
  }, 2400);
}

function setToday(){
  $("todayLabel").textContent = new Date().toLocaleDateString("ru-RU", {
    day:"numeric", month:"long", year:"numeric"
  });
}

function applyTheme(mode){
  document.documentElement.classList.toggle("light", mode === "light");
  state.theme = mode;
  localStorage.setItem("asm-theme", mode);
  setTimeout(fitStatTexts, 30);
}

function toggleTheme(){
  applyTheme(state.theme === "dark" ? "light" : "dark");
}

function updateProjectCard(){
  const name = $("boardNameInput").value.trim();
  $("statProjectName").textContent = name || "—";
  $("headerProjectName").textContent = name || "создание-проекта-printer-asm";
  fitStatTexts();
}

function updateChangedCounter(){
  const total = document.querySelectorAll(".tracked-input").length + 5;
  $("statChangedFields").textContent = state.changedFields.size;
  $("statChangedFieldsTotal").textContent = `/${total}`;
}

function setPrinterStatus(isOnline){
  state.printerOnline = isOnline;
  $("statPrinterStatus").textContent = isOnline ? "online" : "offline";
  $("statPrinterStatus").style.color = isOnline ? "var(--success)" : "var(--danger)";
  $("statPrinterStatusSub").textContent = isOnline ? "подключено" : "не подключено";
}

function setLastGenerationNow(){
  const time = new Date().toLocaleString("ru-RU");
  state.lastGenerationTime = time;
  $("statLastGeneration").textContent = time;
}

function markDirty(el, key){
  const hasValue = String(el.value).trim() !== "";
  if (hasValue) {
    el.classList.add("is-dirty");
    state.changedFields.add(key);
  } else {
    el.classList.remove("is-dirty");
    state.changedFields.delete(key);
  }
  updateChangedCounter();
}

function getNum(id){
  const v = parseFloat($(id).value);
  return Number.isFinite(v) ? v : null;
}

function updateCommentAutoPrefix(){
  const boardY = getNum("boardYInput");
  if (boardY === null) return;

  const autoPrefix = String(Math.round(270 + boardY / 2));
  const current = $("commentInput").value;

  if (!state.commentWasManuallyEdited || current.trim() === "") {
    $("commentInput").value = autoPrefix;
    markDirty($("commentInput"), "0x2710");
  }
}

function updateCenterBoardX0Auto(){
  const isAuto = state.values["0x7613"] === 0;
  const x = getNum("boardXInput");
  const input = $("centerBoardX0");

  if (isAuto) {
    input.disabled = true;
    if (x !== null) {
      input.value = String(x / 2);
      markDirty(input, "0x0046");
    }
  } else {
    input.disabled = false;
  }
}

function updateStopBoardYAuto(){
  if (state.stopBoardYWasManuallyEdited) return;
  const y = getNum("boardYInput");
  if (y === null) return;

  const val = Math.round((y * 0.70) * 1000) / 1000;
  $("stopBoardY").value = String(val);
  markDirty($("stopBoardY"), "0x0047");
}

function updateRefFieldsByCount(){
  const isThree = state.values["refCount"] === 3;
  state.values["0x0032"] = isThree ? 1 : 0;

  $("ref3x").disabled = !isThree;
  $("ref3y").disabled = !isThree;

  if (!isThree) {
    $("ref3x").value = "";
    $("ref3y").value = "";
    $("ref3x").classList.remove("is-dirty");
    $("ref3y").classList.remove("is-dirty");
    state.changedFields.delete("0x0037");
    state.changedFields.delete("0x0038");
  }

  updateChangedCounter();
}

function setupToggle(containerId, stateKey, onChange=null){
  const wrap = $(containerId);
  const buttons = wrap.querySelectorAll(".toggle-btn");

  buttons.forEach(btn => {
    btn.addEventListener("click", () => {
      buttons.forEach(b => b.classList.remove("active"));
      btn.classList.add("active");

      const raw = btn.dataset.value;
      state.values[stateKey] = /^\d+$/.test(raw) ? Number(raw) : raw;
      state.changedFields.add(stateKey);
      updateChangedCounter();

      if (onChange) onChange();
    });
  });
}

function updateSimilarProjects(){
  const val = $("boardNameInput").value.trim().toLowerCase();
  const list = $("similarProjectsList");

  if (!val) {
    list.textContent = "Начните вводить название проекта.";
    return;
  }

  const match = val.match(/^nsft(\d{6,})/i);
  if (!match) {
    list.textContent = "Для поиска введите имя в формате nsft...";
    return;
  }

  const prefix = "nsft" + match[1].slice(0, 6);
  const found = demoProjects.filter(x => x.toLowerCase().startsWith(prefix));

  if (!found.length) {
    list.textContent = "Похожие проекты не найдены.";
    return;
  }

  list.innerHTML = found.map(x => `<div style="padding:5px 0">${x}</div>`).join("");
}

function fitTextElement(el, min=18, max=32){
  if (!el) return;
  el.style.fontSize = max + "px";
  let current = max;

  while (current > min && (el.scrollWidth > el.clientWidth || el.scrollHeight > el.clientHeight)) {
    current -= 1;
    el.style.fontSize = current + "px";
  }
}

function fitStatTexts(){
  const el = $("statProjectName");
  if (el) fitTextElement(el, 18, 32);
}

function checkPrinter(){
  setPrinterStatus(true);
  showToast("Проверка сети выполнена (демо)", "success");
}

function resetForm(){
  document.querySelectorAll(".tracked-input").forEach(input => {
    input.value = "";
    input.disabled = false;
    input.classList.remove("is-dirty");
  });

  $("boardNameInput").value = "";
  $("commentInput").value = "";
  $("newFieldId").value = "";
  $("newFieldName").value = "";
  $("newFieldComment").value = "";

  state.changedFields.clear();
  state.stopBoardYWasManuallyEdited = false;
  state.commentWasManuallyEdited = false;

  state.values["0x0032"] = 0;
  state.values["0x7613"] = 0;
  state.values["0x765D"] = 0;
  state.values["refCount"] = 2;
  state.values.printDirectionGroup = "B";

  document.querySelectorAll("#refCountToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 0);
  });
  document.querySelectorAll("#boardStopModeToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 0);
  });
  document.querySelectorAll("#boardSideToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 0);
  });
  document.querySelectorAll("#printDirectionToggle .toggle-btn").forEach((b, i) => {
    b.classList.toggle("active", i === 1);
  });

  updateRefFieldsByCount();
  updateCenterBoardX0Auto();
  updateChangedCounter();
  updateProjectCard();
  updateSimilarProjects();
  fitStatTexts();
  showToast("Форма сброшена", "success");
}

function generateProject(){
  const boardName = $("boardNameInput").value.trim();
  if (!boardName) {
    showToast("Заполните Название платы", "warn");
    return;
  }

  setLastGenerationNow();

  const payload = {
    boardName,
    values: {
      "0x000B": $("boardXInput").value,
      "0x000A": $("boardYInput").value,
      "0x000C": $("boardThicknessInput").value,
      "0x2710": $("commentInput").value,
      "0x0032": state.values["0x0032"],
      "0x0033": $("ref1x").value,
      "0x0034": $("ref1y").value,
      "0x0035": $("ref2x").value,
      "0x0036": $("ref2y").value,
      "0x0037": $("ref3x").value,
      "0x0038": $("ref3y").value,
      "0x7613": state.values["0x7613"],
      "0x0046": $("centerBoardX0").value,
      "0x0047": $("stopBoardY").value,
      "0x765D": state.values["0x765D"],
      "0x0010": $("frontPressure").value,
      "0x0011": $("rearPressure").value,
      "0x0015": $("squeegeePasses").value,
      "0x0013": $("separationRate").value,
      "0x2715": $("separationDistance").value,
      "0x0023": $("pasteStirrings").value,
      "0x0028": $("cleaningFrequency").value,
      "0x766C": $("mixingPressure").value,
      "0x766D": $("mixingSpeed").value,
      "0x0020": $("centerBoardMinus").value,
      "0x0021": $("centerBoard3").value,
      "0x193E": $("centerBoardCommon").value,
      "printDirectionGroup": state.values.printDirectionGroup
    }
  };

  console.log("Готово к генерации:", payload);
  showToast("Данные собраны. Реальную запись файлов подключим следующим этапом.", "success");
}

function addNewField(){
  const id = $("newFieldId").value.trim();
  const name = $("newFieldName").value.trim();
  const comment = $("newFieldComment").value.trim();

  if (!id || !name) {
    showToast("Заполните ID и Имя", "warn");
    return;
  }

  console.log("Добавить в карту:", { id, name, comment });
  showToast(`Поле ${id} добавлено в список (демо)`, "success");
}

function bindTrackedInputs(){
  document.querySelectorAll(".tracked-input").forEach(input => {
    const key = input.dataset.id || input.id;

    input.addEventListener("input", () => {
      markDirty(input, key);
    });
  });
}

function init(){
  applyTheme(state.theme);
  setToday();
  updateChangedCounter();
  setPrinterStatus(false);

  $("themeToggle").addEventListener("click", toggleTheme);
  $("checkPrinterBtn").addEventListener("click", checkPrinter);
  $("printerStatusCard").addEventListener("click", checkPrinter);
  $("resetFormBtn").addEventListener("click", resetForm);
  $("generateBtn").addEventListener("click", generateProject);
  $("addFieldBtn").addEventListener("click", addNewField);

  $("boardNameInput").addEventListener("input", () => {
    $("boardNameInput").classList.toggle("is-dirty", $("boardNameInput").value.trim() !== "");
    if ($("boardNameInput").value.trim() !== "") state.changedFields.add("boardName");
    else state.changedFields.delete("boardName");
    updateChangedCounter();
    updateProjectCard();
    updateSimilarProjects();
  });

  $("commentInput").addEventListener("input", () => {
    state.commentWasManuallyEdited = true;
    markDirty($("commentInput"), "0x2710");
  });

  $("boardXInput").addEventListener("input", () => {
    updateCenterBoardX0Auto();
  });

  $("boardYInput").addEventListener("input", () => {
    updateCommentAutoPrefix();
    updateStopBoardYAuto();
  });

  $("stopBoardY").addEventListener("input", () => {
    state.stopBoardYWasManuallyEdited = true;
  });

  setupToggle("refCountToggle", "refCount", updateRefFieldsByCount);
  setupToggle("boardStopModeToggle", "0x7613", updateCenterBoardX0Auto);
  setupToggle("boardSideToggle", "0x765D");
  setupToggle("printDirectionToggle", "printDirectionGroup");

  bindTrackedInputs();

  state.values["refCount"] = 2;
  updateRefFieldsByCount();
  updateCenterBoardX0Auto();
  updateSimilarProjects();

  lucide.createIcons();
  fitStatTexts();
  window.addEventListener("resize", fitStatTexts);
}

init();
</script>
