};

const demoProjects = [
  "nsft080100.003_20250908_T",
  "nsft080100.004_20250911_B",
  "nsft080100.006_20200603_B"
];

function $(id){ return document.getElementById(id); }

function applyTheme(mode){
  document.documentElement.classList.toggle("light", mode === "light");
  localStorage.setItem("asm-theme", mode);
  state.theme = mode;
}

function setToday(){
  $("todayLabel").textContent = new Date().toLocaleDateString("ru-RU", {
    day:"numeric", month:"long", year:"numeric"
  });
}

function fitTextElement(el, min=18, max=32){
  if (!el) return;
  el.style.fontSize = max + "px";
  let current = max;
  while (current > min && (el.scrollWidth > el.clientWidth || el.scrollHeight > el.clientHeight)) {
    current -= 1;
    el.style.fontSize = current + "px";
  }
}

function updateProjectCard(){
  const v = document.querySelector('[data-field-id="board_name"]')?.value?.trim() || "";
  $("statProjectName").textContent = v || "—";
  $("headerProjectName").textContent = v || "создание-проекта-printer-asm";
  fitTextElement($("statProjectName"), 18, 32);
}

function updateChangedCounter(){
  $("statChangedFields").textContent = state.changedFields.size;
  $("statChangedFieldsTotal").textContent = `/${Object.keys(fieldMeta).length}`;
}

function updateSimilarProjects(){
  const input = document.querySelector('[data-field-id="board_name"]');
  const val = input?.value?.trim().toLowerCase() || "";
  const list = $("similarProjectsList");

  if (!val) {
    list.textContent = "Начните вводить название проекта.";
    return;
  }

  const match = val.match(/^nsft(\d{6,})/i);
  if (!match) {
    list.textContent = "Для поиска введите имя в формате nsft...";
    return;
  }

  const prefix = "nsft" + match[1].slice(0, 6);
  const found = demoProjects.filter(x => x.toLowerCase().startsWith(prefix));

  list.innerHTML = found.length
    ? found.map(x => `<div style="padding:5px 0">${x}</div>`).join("")
    : "Похожие проекты не найдены.";
}

function getGridClass(cols){
  return {
    1: "grid grid-cols-1 gap-4",
    2: "grid grid-cols-1 md:grid-cols-2 gap-4",
    3: "grid grid-cols-1 md:grid-cols-3 gap-4",
    4: "grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4"
  }[cols] || "grid grid-cols-1 md:grid-cols-3 gap-4";
}

function makeInput(fieldId){
  const meta = fieldMeta[fieldId] || { type:"number", label:fieldId };
  const wrapper = document.createElement("div");

  if (meta.type === "toggle_ref") {
    wrapper.className = "md:col-span-3";
    wrapper.innerHTML = `
      <div class="field-label">${meta.label}</div>
      <div class="toggle-wrap compact" id="refCountToggle">
        <button class="toggle-btn active" data-value="2">2</button>
        <button class="toggle-btn" data-value="3">3</button>
      </div>
    `;
    return wrapper;
  }

  if (meta.type === "toggle_stop_mode") {
    wrapper.innerHTML = `
      <div class="field-label">${meta.label}</div>
      <div class="toggle-wrap compact" id="boardStopModeToggle">
        <button class="toggle-btn active" data-value="0">Авто</button>
        <button class="toggle-btn" data-value="1">Вручную</button>
      </div>
    `;
    return wrapper;
  }

  if (meta.type === "toggle_side") {
    wrapper.innerHTML = `
      <div class="field-label">${meta.label}</div>
      <div class="toggle-wrap compact" id="boardSideToggle">
        <button class="toggle-btn active" data-value="0">Top</button>
        <button class="toggle-btn" data-value="1">Bottom</button>
      </div>
    `;
    return wrapper;
  }

  if (meta.type === "toggle_direction") {
    wrapper.innerHTML = `
      <div class="field-label">${meta.label}</div>
      <div class="toggle-wrap medium" id="printDirectionToggle">
        <button class="toggle-btn" data-value="A">Backward</button>
        <button class="toggle-btn active" data-value="B">Forward</button>
      </div>
    `;
    return wrapper;
  }

  const type = meta.type === "text" ? "text" : "number";
  const step = meta.type === "text" ? "" : 'step="any"';
  const maxLength = fieldId === "0x2710" ? 'maxlength="32"' : "";

  wrapper.innerHTML = `
    <div class="field-label">${meta.label}</div>
    <input
      class="field-input dynamic-input"
      data-field-id="${fieldId}"
      type="${type}"
      ${step}
      ${maxLength}
    />
    ${meta.helper ? `<div class="helper">${meta.helper}</div>` : ``}
  `;
  return wrapper;
}

function renderBlocks(){
  const container = $("dynamicBlocksContainer");
  container.innerHTML = "";

  uiBlocks.blocks.forEach(block => {
    const card = document.createElement("div");
    card.className = "section-card p-4";

    const title = document.createElement("h2");
    title.className = "section-title";
    title.textContent = block.title;

    const grid = document.createElement("div");
    grid.className = getGridClass(block.columns);

    block.fields.forEach(fid => {
      grid.appendChild(makeInput(fid));
    });

    card.appendChild(title);
    card.appendChild(grid);
    container.appendChild(card);
  });

  bindDynamicInputs();
  refreshBlockSelects();
}

function bindDynamicInputs(){
  document.querySelectorAll(".dynamic-input").forEach(input => {
    input.addEventListener("input", () => {
      const key = input.dataset.fieldId;
      if (input.value.trim()) state.changedFields.add(key);
      else state.changedFields.delete(key);

      input.classList.toggle("is-dirty", input.value.trim() !== "");
      updateChangedCounter();

      if (key === "board_name") {
        updateProjectCard();
        updateSimilarProjects();
      }

      if (key === "0x2710") {
        state.commentWasManuallyEdited = true;
      }

      if (key === "0x000A") {
        updateCommentAutoPrefix();
        updateStopBoardYAuto();
      }

      if (key === "0x000B") {
        updateCenterBoardX0Auto();
      }

      if (key === "0x0047") {
        state.stopBoardYWasManuallyEdited = true;
      }
    });
  });

  setupToggle("refCountToggle", "ref_count", updateRefFieldsByCount);
  setupToggle("boardStopModeToggle", "0x7613", updateCenterBoardX0Auto);
  setupToggle("boardSideToggle", "0x765D");
  setupToggle("printDirectionToggle", "print_direction");

  updateRefFieldsByCount();
  updateCenterBoardX0Auto();
}

function setupToggle(containerId, stateKey, onChange=null){
  const wrap = $(containerId);
  if (!wrap) return;

  const buttons = wrap.querySelectorAll(".toggle-btn");
  buttons.forEach(btn => {
    btn.onclick = () => {
      buttons.forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      const raw = btn.dataset.value;
      state.values[stateKey] = /^\d+$/.test(raw) ? Number(raw) : raw;
      state.changedFields.add(stateKey);
      updateChangedCounter();
      if (onChange) onChange();
    };
  });
}

function getFieldInput(fieldId){
  return document.querySelector(`[data-field-id="${fieldId}"]`);
}

function getNumField(fieldId){
  const input = getFieldInput(fieldId);
  if (!input) return null;
  const v = parseFloat(input.value);
  return Number.isFinite(v) ? v : null;
}

function updateCommentAutoPrefix(){
  const boardY = getNumField("0x000A");
  if (boardY === null) return;

  const commentInput = getFieldInput("0x2710");
  if (!commentInput) return;

  const autoPrefix = String(Math.round(270 + boardY / 2));
  if (!state.commentWasManuallyEdited || commentInput.value.trim() === "") {
    commentInput.value = autoPrefix;
    commentInput.classList.add("is-dirty");
    state.changedFields.add("0x2710");
    updateChangedCounter();
  }
}

function updateCenterBoardX0Auto(){
  const isAuto = state.values["0x7613"] === 0;
  const x = getNumField("0x000B");
  const input = getFieldInput("0x0046");
  if (!input) return;

  if (isAuto) {
    input.disabled = true;
    if (x !== null) {
      input.value = String(x / 2);
      input.classList.add("is-dirty");
      state.changedFields.add("0x0046");
      updateChangedCounter();
    }
  } else {
    input.disabled = false;
  }
}

function updateStopBoardYAuto(){
  if (state.stopBoardYWasManuallyEdited) return;
  const y = getNumField("0x000A");
  const input = getFieldInput("0x0047");
  if (y === null || !input) return;

  const val = Math.round((y * 0.70) * 1000) / 1000;
  input.value = String(val);
  input.classList.add("is-dirty");
  state.changedFields.add("0x0047");
  updateChangedCounter();
}

function updateRefFieldsByCount(){
  const isThree = state.values["ref_count"] === 3;
  state.values["0x0032"] = isThree ? 1 : 0;

  const ref3x = getFieldInput("0x0037");
  const ref3y = getFieldInput("0x0038");

  if (ref3x) ref3x.disabled = !isThree;
  if (ref3y) ref3y.disabled = !isThree;

  if (!isThree) {
    if (ref3x) ref3x.value = "";
    if (ref3y) ref3y.value = "";
    state.changedFields.delete("0x0037");
    state.changedFields.delete("0x0038");
    updateChangedCounter();
  }
}

function refreshBlockSelects(){
  const target = $("targetBlockSelect");
  const del = $("deleteBlockSelect");
  target.innerHTML = "";
  del.innerHTML = "";

  uiBlocks.blocks.forEach(block => {
    const o1 = document.createElement("option");
    o1.value = block.id;
    o1.textContent = block.title;
    target.appendChild(o1);

    const o2 = document.createElement("option");
    o2.value = block.id;
    o2.textContent = block.title;
    del.appendChild(o2);
  });
}

function addFieldToBlock(){
  const id = $("newFieldId").value.trim();
  const name = $("newFieldName").value.trim();
  const comment = $("newFieldComment").value.trim();
  const targetBlockId = $("targetBlockSelect").value;
  const columns = Number($("newBlockColumns").value);

  if (!id || !name) {
    alert("Заполните ID и Имя");
    return;
  }

  fieldMeta[id] = {
    type: "text",
    label: name,
    helper: comment || ""
  };

  const block = uiBlocks.blocks.find(b => b.id === targetBlockId);
  if (block) {
    block.fields.push(id);
    block.columns = columns;
  }

  renderBlocks();
  lucide.createIcons();
  alert("Поле добавлено в память страницы. Для постоянного сохранения это нужно записывать в pr1_known_map.json и ui_blocks.json через Electron.");
}

function deleteBlock(){
  const blockId = $("deleteBlockSelect").value;
  const block = uiBlocks.blocks.find(b => b.id === blockId);

  if (!block) return;
  if (!block.deletable) {
    alert("Этот блок защищён от удаления.");
    return;
  }

  if (!confirm(`Удалить блок "${block.title}"?`)) return;

  uiBlocks.blocks = uiBlocks.blocks.filter(b => b.id !== blockId);
  renderBlocks();
  lucide.createIcons();
  alert("Блок удалён из памяти страницы. Для постоянного удаления это нужно записывать в ui_blocks.json через Electron.");
}

function init(){
  applyTheme(state.theme);
  setToday();
  $("themeToggle").onclick = () => applyTheme(state.theme === "dark" ? "light" : "dark");
  $("addFieldBtn").onclick = addFieldToBlock;
  $("deleteBlockBtn").onclick = deleteBlock;
  renderBlocks();
  updateProjectCard();
  updateSimilarProjects();
  updateChangedCounter();
  lucide.createIcons();
}

init();
</script>
</body>
</html>
```

