<script>
const state = {
  theme: localStorage.getItem("asm-theme") || "dark",
  changedFields: new Set(),
  values: {
    refCount: 2,
    boardStopMode: 0,
    boardSide: 0,
    printDirection: "B"
  },
  stopBoardYWasManuallyEdited: false,
  commentWasManuallyEdited: false
};

const templateDefaults = {
  boardThicknessInput: "1.6",
  frontPressure: "4",
  rearPressure: "4",
  squeegeePasses: "1",
  separationRate: "20",
  separationDistance: "3",
  pasteStirrings: "2",
  cleaningFrequency: "10",
  mixingPressure: "3",
  mixingSpeed: "15",
  centerBoardMinus: "",
  centerBoard3: "",
  centerBoardCommon: "",
  ref1x: "",
  ref1y: "",
  ref2x: "",
  ref2y: "",
  ref3x: "",
  ref3y: "",
  stopBoardY: ""
};

const demoProjects = [
  "nsft080100.003_20250908_T",
  "nsft080100.004_20250911_B",
  "nsft080100.006_20200603_B"
];

function $(id){ return document.getElementById(id); }

function applyTheme(mode){
  document.documentElement.classList.toggle("light", mode === "light");
  localStorage.setItem("asm-theme", mode);
  state.theme = mode;
  setTimeout(fitProjectText, 30);
}

function setToday(){
  $("todayLabel").textContent = new Date().toLocaleDateString("ru-RU", {
    day:"numeric", month:"long", year:"numeric"
  });
}

function fitTextElement(el, min=18, max=32){
  if (!el) return;
  el.style.fontSize = max + "px";
  let current = max;
  while (current > min && (el.scrollWidth > el.clientWidth || el.scrollHeight > el.clientHeight)) {
    current -= 1;
    el.style.fontSize = current + "px";
  }
}

function fitProjectText(){
  fitTextElement($("statProjectName"), 18, 32);
}

function updateProjectCard(){
  const v = $("boardNameInput").value.trim();
  $("statProjectName").textContent = v || "—";
  $("headerProjectName").textContent = v || "создание-проекта-printer-asm";
  fitProjectText();
}

function updateChangedCounter(){
  $("statChangedFields").textContent = state.changedFields.size;
  $("statChangedFieldsTotal").textContent = "/18";
}

function updateSimilarProjects(){
  const val = $("boardNameInput").value.trim().toLowerCase();
  const list = $("similarProjectsList");

  if (!val) {
    list.textContent = "Начните вводить название проекта.";
    return;
  }

  const match = val.match(/^nsft(\d{6,})/i);
  if (!match) {
    list.textContent = "Для поиска введите имя в формате nsft...";
    return;
  }

  const prefix = "nsft" + match[1].slice(0, 6);
  const found = demoProjects.filter(x => x.toLowerCase().startsWith(prefix));

  list.innerHTML = found.length
    ? found.map(x => `<div style="padding:5px 0">${x}</div>`).join("")
    : "Похожие проекты не найдены.";
}

function getNum(id){
  const v = parseFloat($(id).value);
  return Number.isFinite(v) ? v : null;
}

function markDirty(input, key){
  const filled = input.value.trim() !== "";
  input.classList.toggle("is-dirty", filled);

  if (filled) state.changedFields.add(key);
  else state.changedFields.delete(key);

  updateChangedCounter();
}

function fillDefaultsFromTemplate(){
  Object.entries(templateDefaults).forEach(([id, value]) => {
    const el = $(id);
    if (!el) return;
    if (el.value.trim() === "") {
      el.value = value;
    }
  });
}

function updateCommentAutoPrefix(){
  const boardY = getNum("boardYInput");
  if (boardY === null) return;

  const autoPrefix = String(Math.round(270 + boardY / 2));
  if (!state.commentWasManuallyEdited || $("commentInput").value.trim() === "") {
    $("commentInput").value = autoPrefix;
    $("commentInput").classList.add("is-dirty");
    state.changedFields.add("comment");
    updateChangedCounter();
  }
}

function updateCenterBoardX0Auto(){
  const x = getNum("boardXInput");
  if (state.values.boardStopMode === 0) {
    $("centerBoardX0").disabled = true;
    if (x !== null) {
      $("centerBoardX0").value = String(x / 2);
      $("centerBoardX0").classList.add("is-dirty");
      state.changedFields.add("centerBoardX0");
      updateChangedCounter();
    }
  } else {
    $("centerBoardX0").disabled = false;
  }
}

function updateStopBoardYAuto(){
  if (state.stopBoardYWasManuallyEdited) return;
  const y = getNum("boardYInput");
  if (y === null) return;

  const val = Math.round((y * 0.7) * 1000) / 1000;
  $("stopBoardY").value = String(val);
  $("stopBoardY").classList.add("is-dirty");
  state.changedFields.add("stopBoardY");
  updateChangedCounter();
}

function updateRefFieldsByCount(){
  const isThree = state.values.refCount === 3;
  $("ref3x").disabled = !isThree;
  $("ref3y").disabled = !isThree;

  if (!isThree) {
    $("ref3x").value = "";
    $("ref3y").value = "";
    $("ref3x").classList.remove("is-dirty");
    $("ref3y").classList.remove("is-dirty");
    state.changedFields.delete("ref3x");
    state.changedFields.delete("ref3y");
    updateChangedCounter();
  }
}

function setupToggle(containerId, key, onChange){
  const wrap = $(containerId);
  const buttons = wrap.querySelectorAll(".toggle-btn");
  buttons.forEach(btn => {
    btn.addEventListener("click", () => {
      buttons.forEach(b => b.classList.remove("active"));
      btn.classList.add("active");
      const raw = btn.dataset.value;
      state.values[key] = /^\d+$/.test(raw) ? Number(raw) : raw;
      state.changedFields.add(key);
      updateChangedCounter();
      if (onChange) onChange();
    });
  });
}

function init(){
  applyTheme(state.theme);
  setToday();

  fillDefaultsFromTemplate();

  $("themeToggle").addEventListener("click", () => {
    applyTheme(state.theme === "dark" ? "light" : "dark");
  });

  $("boardNameInput").addEventListener("input", () => {
    markDirty($("boardNameInput"), "boardName");
    updateProjectCard();
    updateSimilarProjects();
  });

  $("commentInput").addEventListener("input", () => {
    state.commentWasManuallyEdited = true;
    markDirty($("commentInput"), "comment");
  });

  [
    "boardXInput","boardYInput","boardThicknessInput",
    "ref1x","ref1y","ref2x","ref2y","ref3x","ref3y",
    "centerBoardX0","stopBoardY",
    "frontPressure","rearPressure","squeegeePasses",
    "separationRate","separationDistance",
    "pasteStirrings","cleaningFrequency","mixingPressure","mixingSpeed",
    "centerBoardMinus","centerBoard3","centerBoardCommon"
  ].forEach(id => {
    $(id).addEventListener("input", () => markDirty($(id), id));
  });

  $("boardXInput").addEventListener("input", updateCenterBoardX0Auto);
  $("boardYInput").addEventListener("input", () => {
    updateCommentAutoPrefix();
    updateStopBoardYAuto();
  });

  $("stopBoardY").addEventListener("input", () => {
    state.stopBoardYWasManuallyEdited = true;
  });

  setupToggle("refCountToggle", "refCount", updateRefFieldsByCount);
  setupToggle("boardStopModeToggle", "boardStopMode", updateCenterBoardX0Auto);
  setupToggle("boardSideToggle", "boardSide");
  setupToggle("printDirectionToggle", "printDirection");

  updateProjectCard();
  updateSimilarProjects();
  updateRefFieldsByCount();
  updateCenterBoardX0Auto();
  updateChangedCounter();

  lucide.createIcons();
  window.addEventListener("resize", fitProjectText);
}

init();
</script>
</body>
</html>
