    -webkit-appearance:none;
    margin:0;
  }

  .field-input:focus{
    outline:none;
    border-color:var(--accent);
    box-shadow:0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
  }

  .field-input.is-dirty{
    border-color:color-mix(in srgb, var(--accent) 70%, var(--border));
    background:color-mix(in srgb, var(--accent) 8%, var(--surface-alt));
  }

  .field-input:disabled{
    opacity:.65;
    cursor:not-allowed;
  }

  .ghost-btn, .solid-btn{
    display:flex;
    align-items:center;
    gap:8px;
    border-radius:10px;
    padding:11px 13px;
    font-size:15px;
    font-weight:600;
  }

  .ghost-btn{
    border:1px solid var(--border);
    background:var(--surface-alt);
    color:var(--text);
  }

  .solid-btn{
    background:var(--accent);
    color:var(--accent-fg);
    justify-content:flex-start;
    text-align:left;
  }

  .solid-btn:disabled,
  .ghost-btn:disabled{
    opacity:.45;
    cursor:not-allowed;
  }

  .toggle-wrap{
    display:flex;
    gap:6px;
    background:var(--surface-alt);
    border:1px solid var(--border);
    border-radius:12px;
    padding:3px;
  }

  .toggle-btn{
    flex:1;
    border:none;
    border-radius:8px;
    padding:7px 10px;
    font-size:14px;
    font-weight:700;
    color:var(--muted);
    background:transparent;
  }

  .toggle-btn.active{
    background:color-mix(in srgb, var(--accent) 18%, transparent);
    color:var(--text);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent);
  }

  .toggle-wrap.compact{
    width:50%;
    min-width:180px;
  }

  .toggle-wrap.medium{
    width:25%;
    min-width:240px;
  }

  .helper{
    font-size:13px;
    color:var(--muted);
    line-height:1.45;
    margin-top:5px;
  }

  .hint-list{
    background:var(--surface-alt);
